window.GEN = {"react": {"examples": {"React: counter + todo": "// @react — React 18 runs right here (JSX is compiled in the browser by Babel).\n// React hooks are in scope: useState, useEffect, useRef, useMemo, useReducer, useCallback.\n\nfunction Counter() {\n  const [n, setN] = useState(0);\n  return (\n    <div className=\"card\">\n      <h3>Counter<\/h3>\n      <div className=\"big\">{n}<\/div>\n      <button onClick={() => setN(n - 1)}>−<\/button>{\" \"}\n      <button onClick={() => setN(0)}>reset<\/button>{\" \"}\n      <button className=\"p\" onClick={() => setN(n + 1)}>+<\/button>\n    <\/div>\n  );\n}\n\nfunction Todos() {\n  const [items, setItems] = useState([\n    { id: 1, text: \"Learn JSX\", done: true },\n    { id: 2, text: \"Build a component\", done: false },\n    { id: 3, text: \"Ship it\", done: false },\n  ]);\n  const [text, setText] = useState(\"\");\n  const left = items.filter(i => !i.done).length;\n  const add = e => {\n    e.preventDefault();\n    if (!text.trim()) return;\n    setItems([...items, { id: Date.now(), text: text.trim(), done: false }]);\n    setText(\"\");\n  };\n  return (\n    <div className=\"card\">\n      <h3>Todos <small>({left} left)<\/small><\/h3>\n      <form onSubmit={add}>\n        <input value={text} onChange={e => setText(e.target.value)} placeholder=\"What needs doing?\" />\n        <button className=\"p\">Add<\/button>\n      <\/form>\n      <ul>\n        {items.map(i => (\n          <li key={i.id} className={i.done ? \"done\" : \"\"}>\n            <label>\n              <input type=\"checkbox\" checked={i.done}\n                onChange={() => setItems(items.map(x => x.id === i.id ? { ...x, done: !x.done } : x))} />\n              {\" \"}{i.text}\n            <\/label>\n            <a onClick={() => setItems(items.filter(x => x.id !== i.id))}>✕<\/a>\n          <\/li>\n        ))}\n      <\/ul>\n    <\/div>\n  );\n}\n\nfunction Clock() {\n  const [now, setNow] = useState(new Date());\n  useEffect(() => {                       // effect with cleanup\n    const t = setInterval(() => setNow(new Date()), 1000);\n    return () => clearInterval(t);\n  }, []);\n  return <div className=\"clock\">{now.toLocaleTimeString()}<\/div>;\n}\n\nfunction App() {\n  return (\n    <div className=\"wrap\">\n      <h2>React in DevPortal <Clock /><\/h2>\n      <div className=\"grid\"><Counter /><Todos /><\/div>\n    <\/div>\n  );\n}\n\nconst style = document.createElement(\"style\");\nstyle.textContent = `\n  .wrap{max-width:760px;margin:24px auto;padding:0 16px;font:15px system-ui,sans-serif;color:${THEME.fg}}\n  h2{display:flex;justify-content:space-between;align-items:center;color:${THEME.accent}}\n  .clock{font:14px ui-monospace,monospace;color:${THEME.muted}}\n  .grid{display:grid;grid-template-columns:1fr 1.6fr;gap:16px}\n  .card{padding:16px;border:1px solid ${THEME.muted}55;border-radius:14px;background:${THEME.bg}}\n  .card h3{margin:0 0 10px} .card h3 small{color:${THEME.muted};font-weight:400}\n  .big{font-size:54px;font-weight:700;margin-bottom:8px}\n  button{padding:7px 12px;border-radius:8px;border:1px solid ${THEME.muted}88;background:transparent;color:inherit;cursor:pointer}\n  button.p{background:${THEME.accent};border-color:${THEME.accent};color:#fff}\n  input[type=text],input:not([type]){padding:7px 10px;border-radius:8px;border:1px solid ${THEME.muted}88;background:transparent;color:inherit;margin-right:6px}\n  ul{list-style:none;padding:0;margin:12px 0 0} li{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid ${THEME.muted}33}\n  li.done label{text-decoration:line-through;opacity:.55} li a{cursor:pointer;color:${THEME.err}}\n`;\ndocument.head.appendChild(style);\nReactDOM.createRoot(document.getElementById(\"root\")).render(<App />);\nconsole.log(\"React\", React.version, \"mounted\");\n", "React: shopping cart (useReducer)": "// @react — useReducer + useMemo: a tiny shop with a cart.\n\nconst PRODUCTS = [\n  { id: \"kb\", name: \"Mechanical keyboard\", price: 129, emoji: \"⌨️\" },\n  { id: \"ms\", name: \"Ergonomic mouse\", price: 79, emoji: \"🖱️\" },\n  { id: \"mo\", name: \"4K monitor\", price: 389, emoji: \"🖥️\" },\n  { id: \"hp\", name: \"Noise-cancelling headphones\", price: 249, emoji: \"🎧\" },\n  { id: \"dk\", name: \"Standing desk\", price: 549, emoji: \"🪑\" },\n  { id: \"cf\", name: \"Coffee for the team\", price: 24, emoji: \"☕\" },\n];\n\nfunction cartReducer(state, action) {\n  switch (action.type) {\n    case \"add\": return { ...state, [action.id]: (state[action.id] || 0) + 1 };\n    case \"dec\": {\n      const q = (state[action.id] || 0) - 1;\n      const next = { ...state };\n      if (q <= 0) delete next[action.id]; else next[action.id] = q;\n      return next;\n    }\n    case \"clear\": return {};\n    default: throw new Error(\"unknown action \" + action.type);\n  }\n}\n\nfunction App() {\n  const [cart, dispatch] = useReducer(cartReducer, {});\n  const [promo, setPromo] = useState(\"\");\n  const lines = useMemo(() => PRODUCTS.filter(p => cart[p.id]).map(p => ({ ...p, qty: cart[p.id] })), [cart]);\n  const subtotal = lines.reduce((s, l) => s + l.price * l.qty, 0);\n  const discount = promo.toUpperCase() === \"DEV10\" ? subtotal * 0.1 : 0;\n  const total = subtotal - discount;\n  useEffect(() => { console.log(\"cart changed:\", JSON.stringify(cart)); }, [cart]);\n\n  return (\n    <div className=\"shop\">\n      <section>\n        <h2>🛍️ DevShop<\/h2>\n        <div className=\"products\">\n          {PRODUCTS.map(p => (\n            <div className=\"prod\" key={p.id}>\n              <div className=\"em\">{p.emoji}<\/div>\n              <div className=\"nm\">{p.name}<\/div>\n              <div className=\"pr\">${p.price}<\/div>\n              <button className=\"p\" onClick={() => dispatch({ type: \"add\", id: p.id })}>Add to cart<\/button>\n            <\/div>\n          ))}\n        <\/div>\n      <\/section>\n      <aside>\n        <h3>Cart {lines.length ? <button onClick={() => dispatch({ type: \"clear\" })}>clear<\/button> : null}<\/h3>\n        {lines.length === 0 && <p className=\"mut\">Your cart is empty.<\/p>}\n        {lines.map(l => (\n          <div className=\"line\" key={l.id}>\n            <span>{l.emoji} {l.name}<\/span>\n            <span className=\"qty\">\n              <button onClick={() => dispatch({ type: \"dec\", id: l.id })}>−<\/button> {l.qty}\n              <button onClick={() => dispatch({ type: \"add\", id: l.id })}>+<\/button>\n            <\/span>\n            <b>${l.price * l.qty}<\/b>\n          <\/div>\n        ))}\n        <input placeholder=\"Promo code (try DEV10)\" value={promo} onChange={e => setPromo(e.target.value)} />\n        <div className=\"sum\"><span>Subtotal<\/span><span>${subtotal.toFixed(2)}<\/span><\/div>\n        {discount > 0 && <div className=\"sum ok\"><span>Promo DEV10<\/span><span>−${discount.toFixed(2)}<\/span><\/div>}\n        <div className=\"sum tot\"><span>Total<\/span><span>${total.toFixed(2)}<\/span><\/div>\n        <button className=\"p full\" disabled={!lines.length} onClick={() => { console.log(\"checkout\", total); dispatch({ type: \"clear\" }); }}>Checkout<\/button>\n      <\/aside>\n    <\/div>\n  );\n}\n\nconst st = document.createElement(\"style\");\nst.textContent = `\n  .shop{display:grid;grid-template-columns:1fr 300px;gap:20px;max-width:980px;margin:20px auto;padding:0 16px;font:14px system-ui,sans-serif;color:${THEME.fg}}\n  @media(max-width:720px){.shop{grid-template-columns:1fr}}\n  h2{margin:0 0 12px;color:${THEME.accent}} h3{display:flex;justify-content:space-between;margin:0 0 10px}\n  .products{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px}\n  .prod{padding:14px;border:1px solid ${THEME.muted}55;border-radius:14px;text-align:center}\n  .em{font-size:38px}.nm{margin:6px 0;min-height:36px}.pr{font-weight:700;margin-bottom:8px}\n  aside{padding:16px;border:1px solid ${THEME.muted}55;border-radius:14px;align-self:start;position:sticky;top:12px;background:${THEME.bg}}\n  .line{display:grid;grid-template-columns:1fr auto auto;gap:8px;padding:6px 0;border-bottom:1px solid ${THEME.muted}33;align-items:center}\n  .qty button{padding:0 7px}.mut{color:${THEME.muted}}\n  .sum{display:flex;justify-content:space-between;padding:4px 0}.sum.ok{color:${THEME.ok}}.tot{font-size:18px;font-weight:700;border-top:1px solid ${THEME.muted}55;margin-top:6px;padding-top:8px}\n  input{width:100%;box-sizing:border-box;margin:10px 0;padding:8px;border-radius:8px;border:1px solid ${THEME.muted}88;background:transparent;color:inherit}\n  button{padding:6px 11px;border-radius:8px;border:1px solid ${THEME.muted}88;background:transparent;color:inherit;cursor:pointer}\n  button.p{background:${THEME.accent};border-color:${THEME.accent};color:#fff}button.full{width:100%;margin-top:8px;padding:10px}button:disabled{opacity:.4}\n`;\ndocument.head.appendChild(st);\nReactDOM.createRoot(document.getElementById(\"root\")).render(<App />);\n", "React: tic-tac-toe": "// @react — the classic React tutorial game, with time travel through the move history.\n\nfunction Square({ value, onClick, win }) {\n  return <button className={\"sq\" + (win ? \" win\" : \"\")} onClick={onClick}>{value}<\/button>;\n}\n\nconst LINES = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];\nfunction calc(sq) {\n  for (const [a, b, c] of LINES) if (sq[a] && sq[a] === sq[b] && sq[a] === sq[c]) return { who: sq[a], line: [a, b, c] };\n  return null;\n}\n\nfunction Game() {\n  const [history, setHistory] = useState([Array(9).fill(null)]);\n  const [step, setStep] = useState(0);\n  const squares = history[step];\n  const result = calc(squares);\n  const xNext = step % 2 === 0;\n\n  function play(i) {\n    if (squares[i] || result) return;\n    const next = squares.slice(); next[i] = xNext ? \"X\" : \"O\";\n    setHistory([...history.slice(0, step + 1), next]);\n    setStep(step + 1);\n  }\n  const status = result ? \"Winner: \" + result.who + \" 🎉\" : step === 9 ? \"Draw!\" : \"Next: \" + (xNext ? \"X\" : \"O\");\n\n  return (\n    <div className=\"game\">\n      <div>\n        <h2>Tic-tac-toe<\/h2>\n        <div className=\"status\">{status}<\/div>\n        <div className=\"board\">\n          {squares.map((v, i) => <Square key={i} value={v} win={result && result.line.includes(i)} onClick={() => play(i)} />)}\n        <\/div>\n      <\/div>\n      <ol>\n        {history.map((_, m) => (\n          <li key={m}><button className={m === step ? \"cur\" : \"\"} onClick={() => setStep(m)}>{m ? \"Go to move #\" + m : \"Go to game start\"}<\/button><\/li>\n        ))}\n      <\/ol>\n    <\/div>\n  );\n}\n\nconst css = document.createElement(\"style\");\ncss.textContent = `\n  .game{display:flex;gap:40px;justify-content:center;margin:30px auto;font:15px system-ui,sans-serif;color:${THEME.fg}}\n  h2{margin:0 0 6px;color:${THEME.accent}}.status{margin-bottom:10px;font-weight:600;min-height:22px}\n  .board{display:grid;grid-template-columns:repeat(3,84px);gap:6px}\n  .sq{height:84px;font-size:40px;font-weight:700;border-radius:12px;border:1px solid ${THEME.muted}88;background:transparent;color:inherit;cursor:pointer}\n  .sq:hover{background:${THEME.accent}22}.sq.win{background:${THEME.ok};color:#fff}\n  ol{margin:0;padding-left:20px}li button{margin:2px 0;padding:4px 10px;border-radius:8px;border:1px solid ${THEME.muted}66;background:transparent;color:inherit;cursor:pointer}\n  li button.cur{background:${THEME.accent};color:#fff;border-color:${THEME.accent}}\n`;\ndocument.head.appendChild(css);\nReactDOM.createRoot(document.getElementById(\"root\")).render(<Game />);\n", "React: data explorer": "// @react — a searchable, sortable data table (useMemo for derived data, controlled inputs, custom hook).\n\nconst DATA = [\n  [\"Python\", \"Guido van Rossum\", 1991, 28.1], [\"JavaScript\", \"Brendan Eich\", 1995, 17.5], [\"Java\", \"James Gosling\", 1995, 12.4],\n  [\"C++\", \"Bjarne Stroustrup\", 1985, 10.3], [\"C\", \"Dennis Ritchie\", 1972, 9.5], [\"TypeScript\", \"Anders Hejlsberg\", 2012, 6.2],\n  [\"Rust\", \"Graydon Hoare\", 2010, 3.1], [\"Go\", \"Griesemer, Pike, Thompson\", 2009, 2.7], [\"Ruby\", \"Yukihiro Matsumoto\", 1995, 1.9],\n  [\"Swift\", \"Chris Lattner\", 2014, 1.6], [\"Kotlin\", \"JetBrains\", 2011, 1.4], [\"Bash\", \"Brian Fox\", 1989, 1.1],\n].map(([name, creator, year, share]) => ({ name, creator, year, share }));\n\nfunction useDebounced(value, ms) {                      // a custom hook\n  const [v, setV] = useState(value);\n  useEffect(() => { const t = setTimeout(() => setV(value), ms); return () => clearTimeout(t); }, [value, ms]);\n  return v;\n}\n\nfunction App() {\n  const [q, setQ] = useState(\"\");\n  const [sort, setSort] = useState({ key: \"share\", dir: -1 });\n  const query = useDebounced(q, 150);\n  const rows = useMemo(() => {\n    const f = DATA.filter(r => (r.name + r.creator).toLowerCase().includes(query.toLowerCase()));\n    return f.sort((a, b) => (a[sort.key] > b[sort.key] ? 1 : -1) * sort.dir);\n  }, [query, sort]);\n  const max = Math.max(...DATA.map(r => r.share));\n  const head = (key, label) => (\n    <th onClick={() => setSort(s => ({ key, dir: s.key === key ? -s.dir : 1 }))}>\n      {label} {sort.key === key ? (sort.dir > 0 ? \"▲\" : \"▼\") : \"\"}\n    <\/th>\n  );\n  return (\n    <div className=\"ex\">\n      <h2>Language explorer <small>{rows.length} of {DATA.length}<\/small><\/h2>\n      <input autoFocus placeholder=\"Search name or creator…\" value={q} onChange={e => setQ(e.target.value)} />\n      <table>\n        <thead><tr>{head(\"name\", \"Language\")}{head(\"creator\", \"Creator\")}{head(\"year\", \"Year\")}{head(\"share\", \"Share\")}<\/tr><\/thead>\n        <tbody>\n          {rows.map(r => (\n            <tr key={r.name}>\n              <td><b>{r.name}<\/b><\/td><td>{r.creator}<\/td><td>{r.year}<\/td>\n              <td><div className=\"bar\"><i style={{ width: (r.share / max * 100) + \"%\" }} /><\/div> {r.share}%<\/td>\n            <\/tr>\n          ))}\n          {!rows.length && <tr><td colSpan=\"4\" className=\"none\">No matches 🤷<\/td><\/tr>}\n        <\/tbody>\n      <\/table>\n    <\/div>\n  );\n}\n\nconst s = document.createElement(\"style\");\ns.textContent = `\n  .ex{max-width:760px;margin:24px auto;padding:0 16px;font:14px system-ui,sans-serif;color:${THEME.fg}}\n  h2{color:${THEME.accent};margin:0 0 10px}h2 small{color:${THEME.muted};font-weight:400;font-size:13px}\n  input{width:100%;box-sizing:border-box;padding:10px 12px;border-radius:10px;border:1px solid ${THEME.muted}88;background:transparent;color:inherit;margin-bottom:12px}\n  table{width:100%;border-collapse:collapse}th{text-align:left;cursor:pointer;color:${THEME.muted};padding:8px;border-bottom:1px solid ${THEME.muted}66;user-select:none}\n  th:hover{color:${THEME.fg}}td{padding:8px;border-bottom:1px solid ${THEME.muted}22}.none{text-align:center;color:${THEME.muted}}\n  .bar{display:inline-block;width:90px;height:8px;border-radius:99px;background:${THEME.muted}33;vertical-align:middle;margin-right:6px}\n  .bar i{display:block;height:100%;border-radius:99px;background:${THEME.accent}}\n`;\ndocument.head.appendChild(s);\nReactDOM.createRoot(document.getElementById(\"root\")).render(<App />);\n"}, "groups": {"Components": ["React: counter + todo", "React: shopping cart (useReducer)", "React: tic-tac-toe", "React: data explorer"]}}, "playcanvas": {"examples": {"PlayCanvas: spinning cube": "// @playcanvas — PlayCanvas 3D engine (global `pc`, `canvas` already on the page)\nconst app = new pc.Application(canvas, {});\napp.setCanvasFillMode(pc.FILLMODE_FILL_WINDOW);\napp.setCanvasResolution(pc.RESOLUTION_AUTO);\nwindow.addEventListener(\"resize\", () => app.resizeCanvas());\n\n// camera\nconst camera = new pc.Entity(\"camera\");\ncamera.addComponent(\"camera\", { clearColor: new pc.Color(0.05, 0.06, 0.1) });\ncamera.setPosition(0, 1.5, 5);\ncamera.lookAt(0, 0, 0);\napp.root.addChild(camera);\n\n// light\nconst sun = new pc.Entity(\"sun\");\nsun.addComponent(\"light\", { type: \"directional\", intensity: 1.4 });\nsun.setEulerAngles(45, 30, 0);\napp.root.addChild(sun);\napp.scene.ambientLight = new pc.Color(0.25, 0.25, 0.3);\n\n// a cube with its own material\nconst mat = new pc.StandardMaterial();\nmat.diffuse = new pc.Color(0.2, 0.6, 1);\nmat.update();\nconst cube = new pc.Entity(\"cube\");\ncube.addComponent(\"render\", { type: \"box\", material: mat });\napp.root.addChild(cube);\n\n// ground\nconst floorMat = new pc.StandardMaterial();\nfloorMat.diffuse = new pc.Color(0.15, 0.15, 0.2);\nfloorMat.update();\nconst floor = new pc.Entity(\"floor\");\nfloor.addComponent(\"render\", { type: \"plane\", material: floorMat });\nfloor.setLocalScale(8, 1, 8);\nfloor.setPosition(0, -1, 0);\napp.root.addChild(floor);\n\nlet t = 0;\napp.on(\"update\", dt => {\n  t += dt;\n  cube.rotate(20 * dt, 35 * dt, 10 * dt);\n  cube.setPosition(0, Math.sin(t * 2) * 0.4, 0);\n});\n\napp.start();\nconsole.log(\"PlayCanvas engine v\" + pc.version + \" is running\");\n", "PlayCanvas: solar system": "// @playcanvas — a tiny solar system: parent/child entities do the orbit maths for you\nconst app = new pc.Application(canvas, {});\napp.setCanvasFillMode(pc.FILLMODE_FILL_WINDOW);\napp.setCanvasResolution(pc.RESOLUTION_AUTO);\nwindow.addEventListener(\"resize\", () => app.resizeCanvas());\napp.scene.ambientLight = new pc.Color(0.12, 0.12, 0.16);\n\nfunction mk(name, color, size, emissive) {\n  const m = new pc.StandardMaterial();\n  m.diffuse = emissive ? new pc.Color(0, 0, 0) : color;\n  if (emissive) m.emissive = color;\n  m.update();\n  const e = new pc.Entity(name);\n  e.addComponent(\"render\", { type: \"sphere\", material: m });\n  e.setLocalScale(size, size, size);\n  return e;\n}\n\nconst cam = new pc.Entity(\"cam\");\ncam.addComponent(\"camera\", { clearColor: new pc.Color(0.01, 0.01, 0.03), farClip: 100 });\ncam.setPosition(0, 9, 12);\ncam.lookAt(0, 0, 0);\napp.root.addChild(cam);\n\nconst sun = mk(\"sun\", new pc.Color(1, 0.8, 0.2), 2, true);\nsun.addComponent(\"light\", { type: \"omni\", color: new pc.Color(1, 0.95, 0.8), intensity: 3, range: 40 });\napp.root.addChild(sun);\n\nconst planets = [\n  { name: \"mercury\", c: [0.7, 0.7, 0.7], r: 0.3, d: 3,   speed: 90 },\n  { name: \"earth\",   c: [0.2, 0.5, 1],   r: 0.5, d: 5,   speed: 50, moon: true },\n  { name: \"mars\",    c: [0.9, 0.35, 0.2], r: 0.4, d: 7,   speed: 35 },\n  { name: \"jupiter\", c: [0.9, 0.7, 0.5], r: 1.1, d: 10,  speed: 18 },\n];\nconst pivots = planets.map(p => {\n  const pivot = new pc.Entity(p.name + \"-pivot\");        // rotating the pivot = orbiting its child\n  const body = mk(p.name, new pc.Color(...p.c), p.r);\n  body.setLocalPosition(p.d, 0, 0);\n  pivot.addChild(body);\n  if (p.moon) {\n    const moonPivot = new pc.Entity(\"moon-pivot\");\n    const moon = mk(\"moon\", new pc.Color(0.8, 0.8, 0.8), 0.15);\n    moon.setLocalPosition(1.1, 0, 0);\n    moonPivot.addChild(moon);\n    body.addChild(moonPivot);\n    pivot.moonPivot = moonPivot;\n  }\n  app.root.addChild(pivot);\n  return { pivot, speed: p.speed };\n});\n\napp.on(\"update\", dt => {\n  pivots.forEach(o => {\n    o.pivot.rotate(0, o.speed * dt, 0);\n    if (o.pivot.moonPivot) o.pivot.moonPivot.rotate(0, 200 * dt, 0);\n  });\n});\napp.start();\nconsole.log(\"planets:\", planets.map(p => p.name).join(\", \"));\n", "PlayCanvas: keyboard + mouse": "// @playcanvas — input: move the cube with WASD / arrow keys, click the canvas to spawn spheres\nconst app = new pc.Application(canvas, { keyboard: new pc.Keyboard(window), mouse: new pc.Mouse(canvas) });\napp.setCanvasFillMode(pc.FILLMODE_FILL_WINDOW);\napp.setCanvasResolution(pc.RESOLUTION_AUTO);\nwindow.addEventListener(\"resize\", () => app.resizeCanvas());\napp.scene.ambientLight = new pc.Color(0.3, 0.3, 0.35);\n\nconst cam = new pc.Entity(\"cam\");\ncam.addComponent(\"camera\", { clearColor: new pc.Color(0.08, 0.09, 0.13) });\ncam.setPosition(0, 10, 8);\ncam.lookAt(0, 0, 0);\napp.root.addChild(cam);\n\nconst light = new pc.Entity(\"light\");\nlight.addComponent(\"light\", { type: \"directional\", intensity: 1.2 });\nlight.setEulerAngles(50, 20, 0);\napp.root.addChild(light);\n\nfunction material(r, g, b) { const m = new pc.StandardMaterial(); m.diffuse = new pc.Color(r, g, b); m.update(); return m; }\n\nconst floor = new pc.Entity(\"floor\");\nfloor.addComponent(\"render\", { type: \"plane\", material: material(0.18, 0.2, 0.26) });\nfloor.setLocalScale(14, 1, 14);\napp.root.addChild(floor);\n\nconst player = new pc.Entity(\"player\");\nplayer.addComponent(\"render\", { type: \"box\", material: material(1, 0.55, 0.15) });\nplayer.setPosition(0, 0.5, 0);\napp.root.addChild(player);\n\nconst balls = [];\napp.mouse.on(pc.EVENT_MOUSEDOWN, e => {\n  // turn the click into a point on the floor (y = 0) by casting a ray from the camera\n  const near = cam.camera.screenToWorld(e.x, e.y, cam.camera.nearClip);\n  const far = cam.camera.screenToWorld(e.x, e.y, cam.camera.farClip);\n  const dir = far.clone().sub(near).normalize();\n  if (Math.abs(dir.y) < 1e-4) return;\n  const k = -near.y / dir.y;\n  const p = near.clone().add(dir.mulScalar(k));\n  const b = new pc.Entity(\"ball\");\n  b.addComponent(\"render\", { type: \"sphere\", material: material(Math.random(), Math.random(), Math.random()) });\n  b.setLocalScale(0.6, 0.6, 0.6);\n  b.setPosition(p.x, 3, p.z);\n  b.vy = 0;\n  app.root.addChild(b);\n  balls.push(b);\n  console.log(\"spawned ball #\" + balls.length + \" at\", p.x.toFixed(1), p.z.toFixed(1));\n});\n\nconst speed = 6;\napp.on(\"update\", dt => {\n  const k = app.keyboard;\n  let x = 0, z = 0;\n  if (k.isPressed(pc.KEY_A) || k.isPressed(pc.KEY_LEFT))  x -= 1;\n  if (k.isPressed(pc.KEY_D) || k.isPressed(pc.KEY_RIGHT)) x += 1;\n  if (k.isPressed(pc.KEY_W) || k.isPressed(pc.KEY_UP))    z -= 1;\n  if (k.isPressed(pc.KEY_S) || k.isPressed(pc.KEY_DOWN))  z += 1;\n  const p = player.getPosition();\n  player.setPosition(p.x + x * speed * dt, 0.5, p.z + z * speed * dt);\n\n  balls.forEach(b => {             // hand-rolled gravity + bounce (no physics engine needed)\n    b.vy -= 9.8 * dt;\n    const q = b.getPosition();\n    let y = q.y + b.vy * dt;\n    if (y < 0.3) { y = 0.3; b.vy = -b.vy * 0.7; }\n    b.setPosition(q.x, y, q.z);\n  });\n});\napp.start();\ncanvas.focus && canvas.setAttribute(\"tabindex\", \"0\");\nconsole.log(\"click the preview once, then use WASD / arrows; click to drop balls\");\n"}, "groups": {"3D": ["PlayCanvas: spinning cube", "PlayCanvas: solar system", "PlayCanvas: keyboard + mouse"]}}, "rustwasm": {"examples": {"Hello, canvas": "// devportal-app: hello_canvas\n//! Hello, canvas — the smallest useful DevPortal Rust app.\n//! Move the mouse: a ring follows it. Click: drop a bouncing ball. Space: clear. Everything below is\n//! plain Rust; the `dp` crate turns draw calls into the browser <canvas>.\nuse dp::{keys, App, Cursor, Gfx, Mods, Pointer, PointerKind, Rgba};\n\nconst BG: Rgba = Rgba::rgb(14, 17, 27);\nconst GRID: Rgba = Rgba::rgba(255, 255, 255, 14);\nconst TEXT: Rgba = Rgba::rgb(220, 226, 240);\nconst DIM: Rgba = Rgba::rgb(130, 140, 165);\n\nstruct Ball { x: f32, y: f32, vx: f32, vy: f32, r: f32, color: Rgba }\n\npub struct Hello { w: f32, h: f32, balls: Vec<Ball>, mouse: (f32, f32), last_t: f64, seed: u32, frames: u32 }\n\nimpl Hello {\n    pub fn new() -> Self {\n        Hello { w: 640.0, h: 400.0, balls: Vec::new(), mouse: (-100.0, -100.0), last_t: 0.0, seed: 0x2545_f491, frames: 0 }\n    }\n    /// tiny deterministic random numbers in 0..1 (xorshift), so tests are reproducible\n    fn rnd(&mut self) -> f32 {\n        let mut x = self.seed;\n        x ^= x << 13; x ^= x >> 17; x ^= x << 5;\n        self.seed = x;\n        (x >> 8) as f32 / (1u32 << 24) as f32\n    }\n    fn spawn(&mut self, x: f32, y: f32) {\n        let (a, b, c, d) = (self.rnd(), self.rnd(), self.rnd(), self.rnd());\n        self.balls.push(Ball {\n            x, y,\n            vx: (a - 0.5) * 360.0,\n            vy: -120.0 - b * 200.0,\n            r: 10.0 + c * 16.0,\n            color: Rgba::rgb(80 + (d * 175.0) as u8, 120 + (a * 120.0) as u8, 255 - (b * 150.0) as u8),\n        });\n        if self.balls.len() > 200 { self.balls.remove(0); }\n    }\n    pub fn step(&mut self, dt: f32) {\n        let (w, h) = (self.w, self.h);\n        for b in &mut self.balls {\n            b.vy += 900.0 * dt;                       // gravity, pixels / s²\n            b.x += b.vx * dt;\n            b.y += b.vy * dt;\n            if b.x < b.r { b.x = b.r; b.vx = -b.vx * 0.9; }\n            if b.x > w - b.r { b.x = w - b.r; b.vx = -b.vx * 0.9; }\n            if b.y > h - b.r { b.y = h - b.r; b.vy = -b.vy * 0.82; if b.vy.abs() < 20.0 { b.vy = 0.0; } }\n        }\n    }\n    pub fn ball_count(&self) -> usize { self.balls.len() }\n}\n\nimpl Default for Hello { fn default() -> Self { Self::new() } }\n\nimpl App for Hello {\n    fn init(&mut self, w: f32, h: f32) {\n        self.w = w; self.h = h;\n        for i in 0..4 { self.spawn(w * (0.2 + 0.2 * i as f32), h * 0.3); }\n    }\n    fn resize(&mut self, w: f32, h: f32) { self.w = w; self.h = h; }\n\n    fn frame(&mut self, g: &mut dyn Gfx, t_ms: f64) {\n        let dt = if self.last_t == 0.0 { 0.016 } else { ((t_ms - self.last_t) / 1000.0).min(0.05) as f32 };\n        self.last_t = t_ms;\n        self.frames += 1;\n        self.step(dt);\n\n        g.clear(BG);\n        let mut x = 0.0;\n        while x < self.w { g.line(x, 0.0, x, self.h, 1.0, GRID); x += 40.0; }\n        let mut y = 0.0;\n        while y < self.h { g.line(0.0, y, self.w, y, 1.0, GRID); y += 40.0; }\n\n        for b in &self.balls {\n            g.circle(b.x, b.y, b.r, b.color, true);\n            g.circle(b.x, b.y, b.r, Rgba::rgba(255, 255, 255, 90), false);\n        }\n        g.circle(self.mouse.0, self.mouse.1, 18.0, Rgba::rgb(255, 196, 61), false);\n\n        g.text(\"Hello from Rust → WebAssembly\", 16.0, 28.0, 18.0, TEXT);\n        g.text(&format!(\"balls: {}   frame: {}\", self.balls.len(), self.frames), 16.0, 50.0, 13.0, DIM);\n        g.text(\"click = drop a ball · space = clear\", 16.0, self.h - 14.0, 12.0, DIM);\n        g.cursor(Cursor::Crosshair);\n    }\n\n    fn pointer(&mut self, p: Pointer) {\n        self.mouse = (p.x, p.y);\n        if p.kind == PointerKind::Down && p.buttons & 1 != 0 { self.spawn(p.x, p.y); }\n    }\n    fn key(&mut self, code: u32, down: bool, _mods: Mods) {\n        if down && code == keys::SPACE { self.balls.clear(); }\n    }\n}\n\ndp::dp_app!(Hello::new());\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    use dp::recorder::{Cmd, Recorder};\n\n    fn app() -> Hello { let mut a = Hello::new(); a.init(640.0, 400.0); a }\n\n    #[test]\n    fn starts_with_four_balls_and_draws_them() {\n        let mut a = app();\n        let mut r = Recorder::new();\n        a.frame(&mut r, 16.0);\n        assert_eq!(a.ball_count(), 4);\n        assert!(matches!(r.cmds[0], Cmd::Clear(_)));\n        assert!(r.texts().iter().any(|t| t.contains(\"balls: 4\")));\n    }\n\n    #[test]\n    fn click_spawns_a_ball_and_space_clears() {\n        let mut a = app();\n        a.pointer(Pointer { kind: PointerKind::Down, x: 100.0, y: 100.0, buttons: 1, delta: 0.0 });\n        assert_eq!(a.ball_count(), 5);\n        a.pointer(Pointer { kind: PointerKind::Move, x: 5.0, y: 5.0, buttons: 0, delta: 0.0 });\n        assert_eq!(a.ball_count(), 5, \"moving must not spawn\");\n        a.key(keys::SPACE, true, Mods(0));\n        assert_eq!(a.ball_count(), 0);\n    }\n\n    #[test]\n    fn balls_stay_inside_the_canvas() {\n        let mut a = app();\n        for _ in 0..2000 { a.step(0.016); }\n        for b in &a.balls {\n            assert!(b.x >= b.r - 0.01 && b.x <= 640.0 - b.r + 0.01, \"x out of range: {}\", b.x);\n            assert!(b.y <= 400.0 - b.r + 0.01, \"fell through the floor: {}\", b.y);\n        }\n    }\n\n    #[test]\n    fn ball_count_is_capped() {\n        let mut a = app();\n        for i in 0..500 { a.spawn(i as f32, 10.0); }\n        assert_eq!(a.ball_count(), 200);\n    }\n}\n", "Home design planner": "// devportal-app: floorplan\n//! Home design planner — draw walls and rooms, drop doors, windows and furniture, read the measurements.\n//! `model.rs` holds all the rules (and the tests); this file is the editor: tools, drawing, mouse and keyboard.\n//!\n//! Tools: V select · W wall · B room · D door · N window · F furniture.  R rotate · Del delete · G snap\n//! · M dimensions · L demo apartment · X export SVG (to the Console) · Ctrl+Z / Ctrl+Y undo / redo.\n//! Mouse wheel zooms, right/middle-drag pans.\npub mod model;\n\nuse dp::{keys, App, Cursor, Gfx, Mods, Pointer, PointerKind, Rgba};\nuse model::{fmt_len, furn_size, len, snap_p, OpenKind, Plan, Sel, CATALOG, P};\n\nconst PANEL_W: f32 = 100.0;\nconst STATUS_H: f32 = 26.0;\nconst SNAP: f32 = 0.5;\n\nconst BG: Rgba = Rgba::rgb(24, 27, 38);\nconst PANEL: Rgba = Rgba::rgb(33, 37, 52);\nconst PANEL_HI: Rgba = Rgba::rgb(58, 66, 96);\nconst ACCENT: Rgba = Rgba::rgb(255, 196, 61);\nconst TEXT: Rgba = Rgba::rgb(222, 228, 242);\nconst DIM: Rgba = Rgba::rgb(135, 145, 170);\nconst WALL: Rgba = Rgba::rgb(232, 235, 245);\nconst SELECT: Rgba = Rgba::rgb(80, 170, 255);\n\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\nenum Tool { Select, Wall, Room, Door, Window, Furniture }\n\n#[derive(Clone, Copy, PartialEq, Debug)]\nenum Act { Tool(Tool), Undo, Redo, Delete, Snap, Dims, Demo, Export, New }\n\nconst BUTTONS: [(&str, Act); 14] = [\n    (\"Select  V\", Act::Tool(Tool::Select)), (\"Wall  W\", Act::Tool(Tool::Wall)), (\"Room  B\", Act::Tool(Tool::Room)),\n    (\"Door  D\", Act::Tool(Tool::Door)), (\"Window  N\", Act::Tool(Tool::Window)), (\"Furniture  F\", Act::Tool(Tool::Furniture)),\n    (\"Undo\", Act::Undo), (\"Redo\", Act::Redo), (\"Delete\", Act::Delete),\n    (\"Snap  G\", Act::Snap), (\"Dims  M\", Act::Dims), (\"Demo  L\", Act::Demo), (\"SVG  X\", Act::Export), (\"New\", Act::New),\n];\n\n#[derive(Clone, Debug)]\nenum Drag { None, Furn { id: u32, off: P }, Wall { id: u32, last: P }, Opening { id: u32 }, Handle { wall: u32, end: u8 } }\n\npub struct Planner {\n    w: f32, h: f32,\n    plan: Plan, undo: Vec<Plan>, redo: Vec<Plan>,\n    tool: Tool, kind: usize, rot: u8,\n    sel: Sel, drag: Drag, drag_start: Option<Plan>,\n    chain: Option<P>, room_start: Option<P>,\n    mouse: P, scale: f32, ox: f32, oy: f32,\n    snap_on: bool, dims: bool,\n    note: String, pending_log: Option<String>,\n}\n\nimpl Planner {\n    pub fn new() -> Self {\n        Planner {\n            w: 800.0, h: 600.0, plan: Plan::sample(), undo: vec![], redo: vec![],\n            tool: Tool::Select, kind: 0, rot: 0, sel: Sel::None, drag: Drag::None, drag_start: None,\n            chain: None, room_start: None, mouse: (0.0, 0.0), scale: 20.0, ox: PANEL_W + 30.0, oy: 40.0,\n            snap_on: true, dims: true, note: \"Demo apartment loaded — pick a tool on the left\".into(), pending_log: None,\n        }\n    }\n\n    // ---------- coordinates ----------\n    fn w2s(&self, p: P) -> P { (p.0 * self.scale + self.ox, p.1 * self.scale + self.oy) }\n    fn s2w(&self, p: P) -> P { ((p.0 - self.ox) / self.scale, (p.1 - self.oy) / self.scale) }\n    fn snapped(&self, p: P) -> P { if self.snap_on { snap_p(p, SNAP) } else { p } }\n    fn in_canvas(&self, p: P) -> bool { p.0 >= PANEL_W && p.1 < self.h - STATUS_H }\n    fn fit(&mut self) {\n        let (cw, ch) = (self.w - PANEL_W - 40.0, self.h - STATUS_H - 60.0);\n        self.scale = (cw / 24.0).min(ch / 16.0).clamp(10.0, 40.0);\n        self.ox = PANEL_W + 20.0 + (cw - 24.0 * self.scale).max(0.0) / 2.0;\n        self.oy = 30.0 + (ch - 16.0 * self.scale).max(0.0) / 2.0;\n    }\n\n    // ---------- history ----------\n    /// Run an edit; keep an undo snapshot only if it really changed something.\n    fn edit(&mut self, f: impl FnOnce(&mut Plan) -> bool) -> bool {\n        let before = self.plan.clone();\n        let changed = f(&mut self.plan);\n        if changed && before != self.plan { self.undo.push(before); self.redo.clear(); if self.undo.len() > 100 { self.undo.remove(0); } true } else { self.plan = before; false }\n    }\n    fn do_undo(&mut self) { if let Some(p) = self.undo.pop() { self.redo.push(std::mem::replace(&mut self.plan, p)); self.sel = Sel::None; } }\n    fn do_redo(&mut self) { if let Some(p) = self.redo.pop() { self.undo.push(std::mem::replace(&mut self.plan, p)); self.sel = Sel::None; } }\n\n    // ---------- actions ----------\n    fn set_tool(&mut self, t: Tool) {\n        self.tool = t; self.chain = None; self.room_start = None; self.drag = Drag::None;\n        if t != Tool::Select { self.sel = Sel::None; }\n        self.note = match t {\n            Tool::Select => \"Click to select · drag to move · drag a wall's end handles · Del removes\",\n            Tool::Wall => \"Click to start a wall, click again to add more · Esc or right-click to stop\",\n            Tool::Room => \"Press, drag and release to draw a rectangular room (4 walls + area)\",\n            Tool::Door => \"Hover a wall and click to place a 3 ft door\",\n            Tool::Window => \"Hover a wall and click to place a 4 ft window\",\n            Tool::Furniture => \"Pick an item, click to place · R rotates\",\n        }.into();\n    }\n    fn act(&mut self, a: Act) {\n        match a {\n            Act::Tool(t) => self.set_tool(t),\n            Act::Undo => self.do_undo(),\n            Act::Redo => self.do_redo(),\n            Act::Delete => { let s = self.sel; if self.edit(|p| p.remove(s)) { self.sel = Sel::None; } }\n            Act::Snap => { self.snap_on = !self.snap_on; self.note = format!(\"Snap to {} ft grid: {}\", SNAP, if self.snap_on { \"on\" } else { \"off\" }); }\n            Act::Dims => { self.dims = !self.dims; }\n            Act::Demo => { self.edit(|p| { *p = Plan::sample(); true }); self.sel = Sel::None; self.fit(); self.note = \"Demo apartment loaded\".into(); }\n            Act::New => { self.edit(|p| { *p = Plan::new(); true }); self.sel = Sel::None; self.note = \"Empty plan — Ctrl+Z brings it back\".into(); }\n            Act::Export => {\n                self.pending_log = Some(self.plan.export_svg());\n                self.note = \"SVG written to the Console tab — copy it into a .svg file\".into();\n            }\n        }\n    }\n    fn rotate(&mut self) {\n        match (self.tool, self.sel) {\n            (_, Sel::Furn(id)) => { self.edit(|p| { p.rotate_furn(id); true }); }\n            (Tool::Furniture, _) => self.rot = (self.rot + 1) % 4,\n            _ => {}\n        }\n    }\n    fn tol(&self) -> f32 { (7.0 / self.scale).max(0.25) }\n\n    // ---------- layout ----------\n    fn button_rect(i: usize) -> (f32, f32, f32, f32) {\n        let gap = if i >= 6 { 12.0 } else { 0.0 };          // a visual break between tools and actions\n        (8.0, 10.0 + i as f32 * 31.0 + gap, PANEL_W - 16.0, 27.0)\n    }\n    fn palette_rect(&self, i: usize) -> (f32, f32, f32, f32) {\n        let (col, row) = ((i % 2) as f32, (i / 2) as f32);\n        (PANEL_W + 8.0 + col * 108.0, 8.0 + row * 24.0 + 20.0, 104.0, 21.0)\n    }\n    fn button_at(p: P) -> Option<usize> {\n        (0..BUTTONS.len()).find(|&i| { let (x, y, w, h) = Self::button_rect(i); p.0 >= x && p.0 <= x + w && p.1 >= y && p.1 <= y + h })\n    }\n    fn palette_at(&self, p: P) -> Option<usize> {\n        if self.tool != Tool::Furniture { return None; }\n        (0..CATALOG.len()).find(|&i| { let (x, y, w, h) = self.palette_rect(i); p.0 >= x && p.0 <= x + w && p.1 >= y && p.1 <= y + h })\n    }\n    fn over_palette(&self, p: P) -> bool { self.tool == Tool::Furniture && p.0 >= PANEL_W && p.0 <= PANEL_W + 224.0 && p.1 <= 8.0 + 6.0 * 24.0 + 26.0 }\n\n    // ---------- drawing ----------\n    fn draw_grid(&self, g: &mut dyn Gfx) {\n        let (a, b) = (self.s2w((PANEL_W, 0.0)), self.s2w((self.w, self.h - STATUS_H)));\n        let step = if self.scale >= 14.0 { 1.0 } else { 5.0 };\n        let mut x = (a.0 / step).floor() * step;\n        while x <= b.0 {\n            let major = (x / 5.0).round() * 5.0 == x;\n            let sx = self.w2s((x, 0.0)).0;\n            g.line(sx, 0.0, sx, self.h - STATUS_H, 1.0, Rgba::rgba(255, 255, 255, if major { 26 } else { 10 }));\n            x += step;\n        }\n        let mut y = (a.1 / step).floor() * step;\n        while y <= b.1 {\n            let major = (y / 5.0).round() * 5.0 == y;\n            let sy = self.w2s((0.0, y)).1;\n            g.line(PANEL_W, sy, self.w, sy, 1.0, Rgba::rgba(255, 255, 255, if major { 26 } else { 10 }));\n            y += step;\n        }\n    }\n\n    fn draw_plan(&self, g: &mut dyn Gfx) {\n        let sc = self.scale;\n        for r in &self.plan.rooms {\n            let (x, y) = self.w2s((r.x, r.y));\n            let hi = self.sel == Sel::Room(r.id);\n            g.rect(x, y, r.w * sc, r.h * sc, if hi { Rgba::rgba(80, 170, 255, 40) } else { Rgba::rgba(120, 150, 220, 22) }, true);\n            let c = self.w2s((r.x + r.w / 2.0, r.y + r.h / 2.0));\n            g.text(&r.name, c.0 - r.name.len() as f32 * 3.4, c.1 - 2.0, 14.0, Rgba::rgba(200, 212, 240, 200));\n            g.text(&format!(\"{:.0} sq ft\", r.w * r.h), c.0 - 24.0, c.1 + 15.0, 11.0, Rgba::rgba(160, 175, 210, 190));\n        }\n        for f in &self.plan.furn {\n            let (w, h) = furn_size(f);\n            let (x, y) = self.w2s((f.x - w / 2.0, f.y - h / 2.0));\n            let (cr, cg, cb) = CATALOG[f.kind].3;\n            g.rect(x, y, w * sc, h * sc, Rgba::rgb(cr, cg, cb), true);\n            g.rect(x, y, w * sc, h * sc, Rgba::rgba(0, 0, 0, 120), false);\n            if w * sc > 46.0 && h * sc > 18.0 { g.text(CATALOG[f.kind].0, x + 4.0, y + 13.0, 10.0, Rgba::rgba(20, 20, 30, 220)); }\n            if self.sel == Sel::Furn(f.id) { g.rect(x - 2.0, y - 2.0, w * sc + 4.0, h * sc + 4.0, SELECT, false); }\n        }\n        let wall_px = (0.5 * sc).max(3.0);\n        for w in &self.plan.walls {\n            let (a, b) = (self.w2s(w.a), self.w2s(w.b));\n            let hi = self.sel == Sel::Wall(w.id);\n            g.line(a.0, a.1, b.0, b.1, wall_px, if hi { SELECT } else { WALL });\n        }\n        for o in &self.plan.openings {\n            let Some(w) = self.plan.wall(o.wall) else { continue };\n            let l = len(w.a, w.b);\n            let (ux, uy) = ((w.b.0 - w.a.0) / l, (w.b.1 - w.a.1) / l);\n            let c = (w.a.0 + (w.b.0 - w.a.0) * o.t, w.a.1 + (w.b.1 - w.a.1) * o.t);\n            self.draw_opening(g, c, (ux, uy), o.width, o.kind, wall_px, self.sel == Sel::Opening(o.id), false);\n        }\n        if self.dims {\n            for w in &self.plan.walls {\n                let (m, l) = (((w.a.0 + w.b.0) / 2.0, (w.a.1 + w.b.1) / 2.0), len(w.a, w.b));\n                let (ux, uy) = ((w.b.0 - w.a.0) / l, (w.b.1 - w.a.1) / l);\n                let s = self.w2s((m.0 - uy * 0.9, m.1 + ux * 0.9));\n                let t = fmt_len(l);\n                g.text(&t, s.0 - t.len() as f32 * 2.8, s.1 + 4.0, 11.0, Rgba::rgba(255, 196, 61, 230));\n            }\n        }\n    }\n\n    /// A door (gap + leaf + swing arc) or window (gap + glass lines) centred at `c` on a wall running along `u`.\n    #[allow(clippy::too_many_arguments)]\n    fn draw_opening(&self, g: &mut dyn Gfx, c: P, u: P, width: f32, kind: OpenKind, wall_px: f32, hi: bool, ghost: bool) {\n        let n = (-u.1, u.0);\n        let (a, b) = ((c.0 - u.0 * width / 2.0, c.1 - u.1 * width / 2.0), (c.0 + u.0 * width / 2.0, c.1 + u.1 * width / 2.0));\n        let (sa, sb) = (self.w2s(a), self.w2s(b));\n        let col = if hi { SELECT } else if ghost { Rgba::rgba(255, 196, 61, 230) } else { Rgba::rgb(200, 210, 235) };\n        g.line(sa.0, sa.1, sb.0, sb.1, wall_px + 2.0, if ghost { Rgba::rgba(24, 27, 38, 200) } else { BG });\n        match kind {\n            OpenKind::Door => {\n                let tip = self.w2s((a.0 + n.0 * width, a.1 + n.1 * width));\n                g.line(sa.0, sa.1, tip.0, tip.1, 2.0, col);\n                let arc: Vec<(f32, f32)> = (0..=12).map(|i| {\n                    let th = (1.0 - i as f32 / 12.0) * std::f32::consts::FRAC_PI_2;\n                    self.w2s((a.0 + width * (th.cos() * u.0 + th.sin() * n.0), a.1 + width * (th.cos() * u.1 + th.sin() * n.1)))\n                }).collect();\n                g.poly(&arc, col.with_alpha(150), false);\n            }\n            OpenKind::Window => {\n                for off in [-0.12, 0.0, 0.12] {\n                    let (p, q) = (self.w2s((a.0 + n.0 * off, a.1 + n.1 * off)), self.w2s((b.0 + n.0 * off, b.1 + n.1 * off)));\n                    g.line(p.0, p.1, q.0, q.1, if off == 0.0 { 2.0 } else { 1.5 }, if hi { SELECT } else { Rgba::rgb(126, 200, 227) });\n                }\n            }\n        }\n    }\n\n    fn draw_overlays(&self, g: &mut dyn Gfx) {\n        // selection handles on a wall\n        if let Sel::Wall(id) = self.sel {\n            if let Some(w) = self.plan.wall(id) {\n                for e in [w.a, w.b] { let s = self.w2s(e); g.circle(s.0, s.1, 6.0, ACCENT, true); g.circle(s.0, s.1, 6.0, Rgba::rgb(20, 20, 30), false); }\n            }\n        }\n        if !self.in_canvas(self.mouse) { return; }\n        let wp = self.s2w(self.mouse);\n        let sp = self.snapped(wp);\n        let sps = self.w2s(sp);\n        match self.tool {\n            Tool::Wall => {\n                if let Some(a) = self.chain {\n                    let (sa, l) = (self.w2s(a), len(a, sp));\n                    g.line(sa.0, sa.1, sps.0, sps.1, (0.5 * self.scale).max(3.0), Rgba::rgba(255, 196, 61, 150));\n                    g.text(&fmt_len(l), (sa.0 + sps.0) / 2.0 + 8.0, (sa.1 + sps.1) / 2.0 - 8.0, 12.0, ACCENT);\n                }\n                g.circle(sps.0, sps.1, 4.0, ACCENT, true);\n            }\n            Tool::Room => {\n                g.circle(sps.0, sps.1, 4.0, ACCENT, true);\n                if let Some(a) = self.room_start {\n                    let sa = self.w2s(a);\n                    g.rect(sa.0.min(sps.0), sa.1.min(sps.1), (sps.0 - sa.0).abs(), (sps.1 - sa.1).abs(), Rgba::rgba(255, 196, 61, 40), true);\n                    g.rect(sa.0.min(sps.0), sa.1.min(sps.1), (sps.0 - sa.0).abs(), (sps.1 - sa.1).abs(), ACCENT, false);\n                    let (dw, dh) = ((sp.0 - a.0).abs(), (sp.1 - a.1).abs());\n                    g.text(&format!(\"{} × {}  ({:.0} sq ft)\", fmt_len(dw), fmt_len(dh), dw * dh), sps.0 + 10.0, sps.1 - 8.0, 12.0, ACCENT);\n                }\n            }\n            Tool::Door | Tool::Window => {\n                let kind = if self.tool == Tool::Door { OpenKind::Door } else { OpenKind::Window };\n                if let Some((id, t, _)) = self.plan.nearest_wall(wp, 0.8) {\n                    if let Some(w) = self.plan.wall(id) {\n                        let l = len(w.a, w.b);\n                        let width = if kind == OpenKind::Door { 3.0 } else { 4.0 };\n                        if l >= width + 0.2 {\n                            let half = width / 2.0 / l;\n                            let t = t.clamp(half, 1.0 - half);\n                            let c = (w.a.0 + (w.b.0 - w.a.0) * t, w.a.1 + (w.b.1 - w.a.1) * t);\n                            self.draw_opening(g, c, ((w.b.0 - w.a.0) / l, (w.b.1 - w.a.1) / l), width, kind, (0.5 * self.scale).max(3.0), false, true);\n                        }\n                    }\n                }\n            }\n            Tool::Furniture => {\n                let ghost = model::Furn { id: 0, kind: self.kind, x: sp.0, y: sp.1, rot: self.rot };\n                let (w, h) = furn_size(&ghost);\n                let (x, y) = self.w2s((sp.0 - w / 2.0, sp.1 - h / 2.0));\n                g.rect(x, y, w * self.scale, h * self.scale, Rgba::rgba(255, 196, 61, 70), true);\n                g.rect(x, y, w * self.scale, h * self.scale, ACCENT, false);\n                g.text(&format!(\"{} {} × {}\", CATALOG[self.kind].0, fmt_len(w), fmt_len(h)), x, y - 6.0, 11.0, ACCENT);\n            }\n            Tool::Select => {}\n        }\n    }\n\n    fn draw_ui(&self, g: &mut dyn Gfx) {\n        // left panel\n        g.rect(0.0, 0.0, PANEL_W, self.h, PANEL, true);\n        g.line(PANEL_W, 0.0, PANEL_W, self.h, 1.0, Rgba::rgba(255, 255, 255, 25));\n        for (i, (label, act)) in BUTTONS.iter().enumerate() {\n            let (x, y, w, h) = Self::button_rect(i);\n            let active = matches!(act, Act::Tool(t) if *t == self.tool) || (*act == Act::Snap && self.snap_on) || (*act == Act::Dims && self.dims);\n            let hot = Self::button_at(self.mouse) == Some(i);\n            let off = (*act == Act::Undo && self.undo.is_empty()) || (*act == Act::Redo && self.redo.is_empty()) || (*act == Act::Delete && self.sel == Sel::None);\n            g.rect(x, y, w, h, if active { Rgba::rgb(70, 95, 160) } else if hot { PANEL_HI } else { Rgba::rgb(42, 47, 66) }, true);\n            if active { g.rect(x, y, 3.0, h, ACCENT, true); }\n            g.text(label, x + 9.0, y + 18.0, 12.0, if off { Rgba::rgba(222, 228, 242, 90) } else { TEXT });\n        }\n        // furniture palette\n        if self.tool == Tool::Furniture {\n            g.rect(PANEL_W + 4.0, 6.0, 224.0, 6.0 * 24.0 + 40.0, Rgba::rgba(33, 37, 52, 238), true);\n            g.text(\"Furniture\", PANEL_W + 12.0, 22.0, 12.0, DIM);\n            for (i, c) in CATALOG.iter().enumerate() {\n                let (x, y, w, h) = self.palette_rect(i);\n                g.rect(x, y, w, h, if i == self.kind { Rgba::rgb(70, 95, 160) } else { Rgba::rgb(42, 47, 66) }, true);\n                g.rect(x + 4.0, y + 5.0, 10.0, 10.0, Rgba::rgb(c.3 .0, c.3 .1, c.3 .2), true);\n                g.text(c.0, x + 20.0, y + 15.0, 11.0, TEXT);\n            }\n        }\n        // status bar\n        g.rect(PANEL_W, self.h - STATUS_H, self.w - PANEL_W, STATUS_H, PANEL, true);\n        let info = match self.sel {\n            Sel::Wall(id) => self.plan.wall(id).map(|w| format!(\"Wall {}\", fmt_len(len(w.a, w.b)))).unwrap_or_default(),\n            Sel::Furn(id) => self.plan.furn.iter().find(|f| f.id == id).map(|f| { let (w, h) = furn_size(f); format!(\"{} {} × {}\", CATALOG[f.kind].0, fmt_len(w), fmt_len(h)) }).unwrap_or_default(),\n            Sel::Room(id) => self.plan.rooms.iter().find(|r| r.id == id).map(|r| format!(\"{} {} × {} = {:.0} sq ft\", r.name, fmt_len(r.w), fmt_len(r.h), r.w * r.h)).unwrap_or_default(),\n            Sel::Opening(id) => self.plan.openings.iter().find(|o| o.id == id).map(|o| format!(\"{} {}\", if o.kind == OpenKind::Door { \"Door\" } else { \"Window\" }, fmt_len(o.width))).unwrap_or_default(),\n            Sel::None => String::new(),\n        };\n        let left = if info.is_empty() { self.note.clone() } else { info };\n        g.text(&left, PANEL_W + 10.0, self.h - 9.0, 12.0, TEXT);\n        let total = format!(\"{:.0} sq ft · {} walls\", self.plan.total_room_area(), self.plan.walls.len());\n        g.text(&total, self.w - total.len() as f32 * 6.3 - 10.0, self.h - 9.0, 12.0, DIM);\n    }\n}\n\nimpl Default for Planner { fn default() -> Self { Self::new() } }\n\nimpl App for Planner {\n    fn init(&mut self, w: f32, h: f32) { self.w = w; self.h = h; self.fit(); }\n    fn resize(&mut self, w: f32, h: f32) { self.w = w; self.h = h; }\n\n    fn frame(&mut self, g: &mut dyn Gfx, _t_ms: f64) {\n        g.clear(BG);\n        self.draw_grid(g);\n        self.draw_plan(g);\n        self.draw_overlays(g);\n        self.draw_ui(g);\n        if let Some(svg) = self.pending_log.take() { g.log(&svg); }\n        g.cursor(if Self::button_at(self.mouse).is_some() { Cursor::Pointer } else if self.tool == Tool::Select { Cursor::Default } else { Cursor::Crosshair });\n    }\n\n    fn pointer(&mut self, p: Pointer) {\n        let prev = self.mouse;\n        self.mouse = (p.x, p.y);\n        let here = (p.x, p.y);\n        if p.kind == PointerKind::Wheel {\n            if self.in_canvas(here) {\n                let before = self.s2w(here);\n                self.scale = (self.scale * 1.0015f32.powf(-p.delta)).clamp(8.0, 90.0);\n                self.ox = here.0 - before.0 * self.scale;\n                self.oy = here.1 - before.1 * self.scale;\n            }\n            return;\n        }\n        if p.kind == PointerKind::Move && p.buttons & 6 != 0 {      // right / middle drag = pan\n            self.ox += here.0 - prev.0; self.oy += here.1 - prev.1;\n            return;\n        }\n        let wp = self.s2w(here);\n        let sp = self.snapped(wp);\n        match p.kind {\n            PointerKind::Down if p.buttons & 2 != 0 => {              // right click: finish a wall chain / cancel\n                self.chain = None; self.room_start = None;\n            }\n            PointerKind::Down if p.buttons & 1 != 0 => {\n                if here.0 < PANEL_W {\n                    if let Some(i) = Self::button_at(here) { self.act(BUTTONS[i].1); }\n                } else if let Some(i) = self.palette_at(here) {\n                    self.kind = i;\n                } else if self.over_palette(here) || !self.in_canvas(here) {\n                    // click on the palette frame or status bar: ignore\n                } else {\n                    self.canvas_down(wp, sp);\n                }\n            }\n            PointerKind::Move => self.canvas_move(wp, sp),\n            PointerKind::Up => self.canvas_up(sp),\n            _ => {}\n        }\n    }\n\n    fn key(&mut self, code: u32, down: bool, mods: Mods) {\n        if !down { return; }\n        if mods.ctrl() || mods.meta() {\n            match code {\n                x if x == keys::letter('z') => { if mods.shift() { self.do_redo() } else { self.do_undo() } }\n                x if x == keys::letter('y') => self.do_redo(),\n                _ => {}\n            }\n            return;\n        }\n        match code {\n            x if x == keys::letter('v') => self.set_tool(Tool::Select),\n            x if x == keys::letter('w') => self.set_tool(Tool::Wall),\n            x if x == keys::letter('b') => self.set_tool(Tool::Room),\n            x if x == keys::letter('d') => self.set_tool(Tool::Door),\n            x if x == keys::letter('n') => self.set_tool(Tool::Window),\n            x if x == keys::letter('f') => self.set_tool(Tool::Furniture),\n            x if x == keys::letter('r') => self.rotate(),\n            x if x == keys::letter('g') => self.act(Act::Snap),\n            x if x == keys::letter('m') => self.act(Act::Dims),\n            x if x == keys::letter('l') => self.act(Act::Demo),\n            x if x == keys::letter('x') => self.act(Act::Export),\n            keys::DELETE | keys::BACKSPACE => self.act(Act::Delete),\n            keys::ESCAPE => { self.chain = None; self.room_start = None; self.drag = Drag::None; self.sel = Sel::None; }\n            keys::LEFT | keys::RIGHT | keys::UP | keys::DOWN => {\n                let step = if mods.shift() { 5.0 } else { SNAP };\n                let (dx, dy) = match code { keys::LEFT => (-step, 0.0), keys::RIGHT => (step, 0.0), keys::UP => (0.0, -step), _ => (0.0, step) };\n                let s = self.sel;\n                self.edit(|p| { p.nudge(s, dx, dy); s != Sel::None });\n            }\n            _ => {}\n        }\n    }\n}\n\nimpl Planner {\n    fn canvas_down(&mut self, wp: P, sp: P) {\n        match self.tool {\n            Tool::Select => {\n                // wall end handles win over everything else\n                if let Sel::Wall(id) = self.sel {\n                    if let Some(w) = self.plan.wall(id) {\n                        let r = 9.0 / self.scale;\n                        let end = if len(wp, w.a) <= r { Some(0) } else if len(wp, w.b) <= r { Some(1) } else { None };\n                        if let Some(end) = end { self.drag_start = Some(self.plan.clone()); self.drag = Drag::Handle { wall: id, end }; return; }\n                    }\n                }\n                self.sel = self.plan.hit_test(wp, self.tol());\n                self.drag_start = Some(self.plan.clone());\n                self.drag = match self.sel {\n                    Sel::Furn(id) => match self.plan.furn.iter().find(|f| f.id == id) { Some(f) => Drag::Furn { id, off: (f.x - wp.0, f.y - wp.1) }, None => Drag::None },\n                    Sel::Wall(id) => Drag::Wall { id, last: sp },\n                    Sel::Opening(id) => Drag::Opening { id },\n                    _ => Drag::None,\n                };\n            }\n            Tool::Wall => match self.chain {\n                None => self.chain = Some(sp),\n                Some(a) => { if self.edit(|p| p.add_wall(a, sp).is_some()) { self.chain = Some(sp); } }\n            },\n            Tool::Room => self.room_start = Some(sp),\n            Tool::Door | Tool::Window => {\n                let kind = if self.tool == Tool::Door { OpenKind::Door } else { OpenKind::Window };\n                if !self.edit(|p| p.add_opening(kind, wp).is_some()) { self.note = \"Click right on a wall that is long enough for it\".into(); }\n            }\n            Tool::Furniture => {\n                let (k, r) = (self.kind, self.rot);\n                self.edit(|p| { p.add_furn(k, sp.0, sp.1, r); true });\n            }\n        }\n    }\n\n    fn canvas_move(&mut self, wp: P, sp: P) {\n        match self.drag.clone() {\n            Drag::Furn { id, off } => {\n                let t = self.snapped((wp.0 + off.0, wp.1 + off.1));\n                if let Some(f) = self.plan.furn.iter_mut().find(|f| f.id == id) { f.x = t.0; f.y = t.1; }\n            }\n            Drag::Wall { id, last } => {\n                let (dx, dy) = (sp.0 - last.0, sp.1 - last.1);\n                if dx != 0.0 || dy != 0.0 { self.plan.nudge(Sel::Wall(id), dx, dy); self.drag = Drag::Wall { id, last: sp }; }\n            }\n            Drag::Opening { id } => self.plan.set_opening_at(id, wp),\n            Drag::Handle { wall, end } => { self.plan.set_wall_end(wall, end, sp); }\n            Drag::None => {}\n        }\n    }\n\n    fn canvas_up(&mut self, sp: P) {\n        if let Some(start) = self.drag_start.take() {\n            if start != self.plan { self.undo.push(start); self.redo.clear(); }\n        }\n        self.drag = Drag::None;\n        if let Some(a) = self.room_start.take() {\n            if self.tool == Tool::Room && !self.edit(|p| p.add_room(a, sp).is_some()) { self.note = \"Drag a rectangle at least 1 ft each way\".into(); }\n        }\n    }\n}\n\ndp::dp_app!(Planner::new());\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    use dp::recorder::Recorder;\n\n    fn app() -> Planner { let mut a = Planner::new(); a.init(900.0, 640.0); a }\n    fn click(a: &mut Planner, x: f32, y: f32) {\n        a.pointer(Pointer { kind: PointerKind::Move, x, y, buttons: 0, delta: 0.0 });\n        a.pointer(Pointer { kind: PointerKind::Down, x, y, buttons: 1, delta: 0.0 });\n        a.pointer(Pointer { kind: PointerKind::Up, x, y, buttons: 0, delta: 0.0 });\n    }\n    /// screen position of a world point in the current view\n    fn at(a: &Planner, x: f32, y: f32) -> (f32, f32) { a.w2s((x, y)) }\n    fn press(a: &mut Planner, c: u32) { a.key(c, true, Mods(0)); }\n\n    #[test]\n    fn every_toolbar_button_is_clickable_and_in_the_panel() {\n        let mut a = app();\n        for (i, (_, act)) in BUTTONS.iter().enumerate() {\n            let (x, y, w, h) = Planner::button_rect(i);\n            assert!(x + w <= PANEL_W && y + h <= 640.0, \"button {i} outside the panel\");\n            assert_eq!(Planner::button_at((x + 2.0, y + 2.0)), Some(i));\n            let _ = act;\n        }\n        let (x, y, _, _) = Planner::button_rect(1);\n        click(&mut a, x + 5.0, y + 5.0);\n        assert_eq!(a.tool, Tool::Wall);\n    }\n\n    #[test]\n    fn drawing_a_room_with_the_mouse_adds_four_walls_and_undo_removes_them() {\n        let mut a = app(); a.act(Act::New);\n        press(&mut a, keys::letter('b'));\n        let (x0, y0) = at(&a, 2.0, 2.0); let (x1, y1) = at(&a, 12.0, 9.0);\n        a.pointer(Pointer { kind: PointerKind::Move, x: x0, y: y0, buttons: 0, delta: 0.0 });\n        a.pointer(Pointer { kind: PointerKind::Down, x: x0, y: y0, buttons: 1, delta: 0.0 });\n        a.pointer(Pointer { kind: PointerKind::Move, x: x1, y: y1, buttons: 1, delta: 0.0 });\n        a.pointer(Pointer { kind: PointerKind::Up, x: x1, y: y1, buttons: 0, delta: 0.0 });\n        assert_eq!((a.plan.walls.len(), a.plan.rooms.len()), (4, 1));\n        assert!((a.plan.total_room_area() - 70.0).abs() < 1e-3);\n        a.key(keys::letter('z'), true, Mods(2));\n        assert_eq!(a.plan.walls.len(), 0, \"ctrl+z undoes the whole room\");\n        a.key(keys::letter('y'), true, Mods(2));\n        assert_eq!(a.plan.walls.len(), 4, \"ctrl+y brings it back\");\n    }\n\n    #[test]\n    fn wall_tool_chains_segments_and_escape_stops() {\n        let mut a = app(); a.act(Act::New);\n        press(&mut a, keys::letter('w'));\n        let p = [(1.0, 1.0), (8.0, 1.0), (8.0, 6.0)];\n        for (x, y) in p { let (sx, sy) = at(&a, x, y); click(&mut a, sx, sy); }\n        assert_eq!(a.plan.walls.len(), 2, \"three clicks = two chained walls\");\n        press(&mut a, keys::ESCAPE);\n        assert!(a.chain.is_none());\n        let (sx, sy) = at(&a, 12.0, 12.0); click(&mut a, sx, sy);\n        assert_eq!(a.plan.walls.len(), 2, \"first click after Esc only starts a new chain\");\n    }\n\n    #[test]\n    fn doors_need_a_wall_and_land_on_it() {\n        let mut a = app(); a.act(Act::New);\n        a.plan.add_wall((0.0, 0.0), (10.0, 0.0));\n        press(&mut a, keys::letter('d'));\n        let (sx, sy) = at(&a, 5.0, 5.0); click(&mut a, sx, sy);\n        assert!(a.plan.openings.is_empty() && a.note.contains(\"wall\"));\n        let (sx, sy) = at(&a, 5.0, 0.1); click(&mut a, sx, sy);\n        assert_eq!(a.plan.openings.len(), 1);\n    }\n\n    #[test]\n    fn select_drag_moves_furniture_and_delete_removes_it() {\n        let mut a = app();\n        let f = a.plan.furn.iter().find(|f| CATALOG[f.kind].0 == \"Sofa\").unwrap().clone();\n        let (sx, sy) = at(&a, f.x, f.y);\n        a.pointer(Pointer { kind: PointerKind::Move, x: sx, y: sy, buttons: 0, delta: 0.0 });\n        a.pointer(Pointer { kind: PointerKind::Down, x: sx, y: sy, buttons: 1, delta: 0.0 });\n        assert_eq!(a.sel, Sel::Furn(f.id));\n        let (tx, ty) = at(&a, f.x + 2.0, f.y - 1.0);\n        a.pointer(Pointer { kind: PointerKind::Move, x: tx, y: ty, buttons: 1, delta: 0.0 });\n        a.pointer(Pointer { kind: PointerKind::Up, x: tx, y: ty, buttons: 0, delta: 0.0 });\n        let moved = a.plan.furn.iter().find(|g| g.id == f.id).unwrap();\n        assert!((moved.x - (f.x + 2.0)).abs() <= SNAP && (moved.y - (f.y - 1.0)).abs() <= SNAP, \"moved to {:?}\", (moved.x, moved.y));\n        let n = a.plan.furn.len();\n        press(&mut a, keys::DELETE);\n        assert_eq!(a.plan.furn.len(), n - 1);\n        a.do_undo(); a.do_undo();\n        assert_eq!(a.plan.furn.iter().find(|g| g.id == f.id).unwrap().x, f.x, \"two undos: restore + move back\");\n    }\n\n    #[test]\n    fn a_click_without_moving_leaves_no_undo_entry() {\n        let mut a = app();\n        let before = a.undo.len();\n        let (sx, sy) = at(&a, 7.0, 8.5); click(&mut a, sx, sy);   // the rug\n        assert_eq!(a.undo.len(), before);\n    }\n\n    #[test]\n    fn zoom_keeps_the_point_under_the_cursor_fixed() {\n        let mut a = app();\n        let (x, y) = (400.0, 300.0);\n        let (w0, s0) = (a.s2w((x, y)), a.scale);\n        a.pointer(Pointer { kind: PointerKind::Wheel, x, y, buttons: 0, delta: -300.0 });\n        let w1 = a.s2w((x, y));\n        assert!((w0.0 - w1.0).abs() < 1e-3 && (w0.1 - w1.1).abs() < 1e-3);\n        assert!(a.scale > s0, \"wheel up zooms in\");\n    }\n\n    #[test]\n    fn frame_draws_panel_plan_and_dimensions_and_export_logs_svg() {\n        let mut a = app();\n        let mut r = Recorder::new();\n        a.frame(&mut r, 0.0);\n        let t = r.texts();\n        assert!(t.iter().any(|s| s.contains(\"Living\")) && t.iter().any(|s| s.contains(\"Select\")));\n        assert!(t.iter().any(|s| s.contains(\"24'\")), \"outer wall length label\");\n        press(&mut a, keys::letter('x'));\n        let mut r2 = Recorder::new();\n        a.frame(&mut r2, 16.0);\n        assert!(r2.cmds.iter().any(|c| matches!(c, dp::recorder::Cmd::Log(s) if s.starts_with(\"<svg\"))));\n    }\n\n    #[test]\n    fn furniture_tool_places_the_selected_item_rotated() {\n        let mut a = app(); a.act(Act::New);\n        press(&mut a, keys::letter('f'));\n        let (x, y, _, _) = a.palette_rect(0);\n        click(&mut a, x + 4.0, y + 4.0);               // pick \"Bed\"\n        assert_eq!(a.kind, 0);\n        press(&mut a, keys::letter('r'));\n        let (sx, sy) = at(&a, 10.0, 10.0); click(&mut a, sx, sy);\n        assert_eq!(a.plan.furn.len(), 1);\n        assert_eq!(a.plan.furn[0].rot, 1);\n    }\n}\n"}, "groups": {"Apps (built by CI)": ["Hello, canvas", "Home design planner"]}}, "ts": {"examples": {"Page: tech landing (Nimbus)": "// A polished tech landing page, built in typed TypeScript. Toggle monthly / yearly pricing.\n\ninterface Feature { icon: string; title: string; text: string }\ninterface Plan { name: string; monthly: number; blurb: string; perks: string[]; hot?: boolean }\n\nconst features: Feature[] = [\n  { icon: \"⚡\", title: \"Instant deploys\", text: \"Push to main and your service is live worldwide in under 12 seconds.\" },\n  { icon: \"🛡️\", title: \"Secure by default\", text: \"Zero-trust networking, secrets vault and automatic TLS on every service.\" },\n  { icon: \"📈\", title: \"Autoscaling\", text: \"From 0 to 10,000 requests per second without touching a config file.\" },\n  { icon: \"🔍\", title: \"Live observability\", text: \"Traces, logs and metrics in one place, correlated automatically.\" },\n  { icon: \"🧩\", title: \"100+ integrations\", text: \"GitHub, GitLab, Slack, PagerDuty, Terraform and every major cloud.\" },\n  { icon: \"🤖\", title: \"AI assistant\", text: \"Ask why a deploy failed and get the fix as a pull request.\" },\n];\nconst plans: Plan[] = [\n  { name: \"Hacker\", monthly: 0, blurb: \"For side projects\", perks: [\"3 services\", \"Community support\", \"Shared runners\"] },\n  { name: \"Team\", monthly: 29, blurb: \"For growing teams\", perks: [\"Unlimited services\", \"Preview environments\", \"SSO\", \"Priority support\"], hot: true },\n  { name: \"Scale\", monthly: 99, blurb: \"For production at scale\", perks: [\"Dedicated runners\", \"99.99% SLA\", \"Audit logs\", \"Solutions engineer\"] },\n];\n\nconst css = `\n*{box-sizing:border-box}\n.lp{font:16px/1.6 -apple-system,Segoe UI,Inter,system-ui,sans-serif;background:#070b16;color:#e6eaf5;min-height:100%}\n.lp a{color:inherit;text-decoration:none}\nnav{position:sticky;top:0;z-index:5;display:flex;align-items:center;gap:26px;padding:14px 6vw;backdrop-filter:blur(12px);background:#070b16cc;border-bottom:1px solid #ffffff14}\nnav .logo{font-weight:800;font-size:20px;letter-spacing:-.5px}\nnav .logo span{background:linear-gradient(90deg,#7c5cff,#27d3ff);-webkit-background-clip:text;color:transparent}\nnav .links{display:flex;gap:22px;margin-left:12px;color:#9aa6c4;font-size:14px}\nnav .links a:hover{color:#fff}\n.btn{display:inline-block;padding:10px 18px;border-radius:10px;font-weight:600;font-size:14px;border:1px solid #ffffff25;cursor:pointer;color:#fff;background:transparent}\n.btn.p{background:linear-gradient(90deg,#7c5cff,#27d3ff);border:0;color:#04101f}\nnav .btn{margin-left:auto}\n.hero{position:relative;text-align:center;padding:90px 6vw 70px;overflow:hidden}\n.hero:before{content:\"\";position:absolute;left:50%;top:-180px;width:900px;height:900px;transform:translateX(-50%);background:radial-gradient(closest-side,#7c5cff55,transparent)}\n.pill{display:inline-block;padding:5px 14px;border:1px solid #7c5cff77;border-radius:99px;font-size:12px;color:#b9a8ff;background:#7c5cff18}\n.hero h1{position:relative;font-size:clamp(36px,6vw,68px);line-height:1.05;margin:18px auto 16px;max-width:900px;letter-spacing:-2px}\n.hero h1 em{font-style:normal;background:linear-gradient(90deg,#7c5cff,#27d3ff);-webkit-background-clip:text;color:transparent}\n.hero p{position:relative;max-width:620px;margin:0 auto 28px;color:#9aa6c4;font-size:18px}\n.term{position:relative;max-width:560px;margin:44px auto 0;text-align:left;background:#0d1426;border:1px solid #ffffff1a;border-radius:14px;padding:16px 18px;font:13px/1.7 ui-monospace,Menlo,monospace;box-shadow:0 30px 80px #000a}\n.term i{color:#27d3ff;font-style:normal}.term b{color:#3ddc97}\n.sec{padding:70px 6vw}\n.sec h2{text-align:center;font-size:34px;letter-spacing:-1px;margin:0 0 8px}\n.sec .sub{text-align:center;color:#9aa6c4;margin-bottom:40px}\n.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:18px;max-width:1100px;margin:0 auto}\n.card{padding:24px;border:1px solid #ffffff14;border-radius:16px;background:linear-gradient(180deg,#0e1730,#0a1124);transition:.2s}\n.card:hover{transform:translateY(-4px);border-color:#7c5cff88}\n.card .ic{font-size:26px;width:48px;height:48px;display:grid;place-items:center;border-radius:12px;background:#7c5cff22;margin-bottom:14px}\n.card h3{margin:0 0 6px;font-size:18px}.card p{margin:0;color:#9aa6c4;font-size:14px}\n.toggle{display:flex;justify-content:center;gap:10px;align-items:center;margin-bottom:30px;color:#9aa6c4}\n.sw{width:50px;height:28px;border-radius:99px;background:#1a2547;position:relative;cursor:pointer;border:1px solid #ffffff22}\n.sw:after{content:\"\";position:absolute;top:3px;left:3px;width:20px;height:20px;border-radius:50%;background:linear-gradient(90deg,#7c5cff,#27d3ff);transition:.2s}\n.sw.on:after{left:25px}\n.save{color:#3ddc97;font-size:12px}\n.price{font-size:44px;font-weight:800;letter-spacing:-2px}.price small{font-size:14px;color:#9aa6c4;font-weight:500;letter-spacing:0}\n.plan.hot{border-color:#7c5cff;box-shadow:0 0 0 1px #7c5cff,0 20px 60px #7c5cff33}\n.plan ul{list-style:none;padding:0;margin:18px 0 22px}.plan li{padding:5px 0;color:#c8d0e8;font-size:14px}.plan li:before{content:\"✓ \";color:#3ddc97}\n.plan .btn{width:100%;text-align:center}\n.cta{margin:30px 6vw 0;padding:54px 6vw;text-align:center;border-radius:24px;background:linear-gradient(120deg,#2a1d7a,#0b5a78)}\n.cta h2{margin:0 0 10px;font-size:34px}.cta p{margin:0 0 22px;color:#cfe}\nfooter{padding:40px 6vw;display:flex;justify-content:space-between;color:#6b7799;font-size:13px;flex-wrap:wrap;gap:10px}\n`;\n\nlet yearly = false;\nconst money = (n: number) => (n === 0 ? \"$0\" : \"$\" + n);\n\nfunction render(): string {\n  return `<style>${css}<\/style><div class=\"lp\">\n  <nav><a class=\"logo\" href=\"#top\"><span>◆<\/span> Nimbus<\/a><div class=\"links\"><a href=\"#f\">Features<\/a><a href=\"#p\">Pricing<\/a><a href=\"#\">Docs<\/a><a href=\"#\">Blog<\/a><\/div><a class=\"btn p\" href=\"#p\">Start free<\/a><\/nav>\n  <header class=\"hero\" id=\"top\"><span class=\"pill\">✨ New · Nimbus AI now writes your runbooks<\/span>\n    <h1>Ship software at the <em>speed of thought<\/em><\/h1>\n    <p>The cloud platform that deploys, scales and observes your code — so your team can focus on the product, not the plumbing.<\/p>\n    <a class=\"btn p\" href=\"#p\">Deploy your first app<\/a> <a class=\"btn\" href=\"#f\">See how it works<\/a>\n    <div class=\"term\"><i>$<\/i> nimbus deploy<br><b>✔<\/b> built in 4.1s<br><b>✔<\/b> 3 regions healthy<br><b>✔<\/b> live at <i>https://app.nimbus.dev<\/i><\/div><\/header>\n  <section class=\"sec\" id=\"f\"><h2>Everything you need to run in production<\/h2><div class=\"sub\">One platform, no glue code.<\/div>\n    <div class=\"grid\">${features.map(f => `<div class=\"card\"><div class=\"ic\">${f.icon}<\/div><h3>${f.title}<\/h3><p>${f.text}<\/p><\/div>`).join(\"\")}<\/div><\/section>\n  <section class=\"sec\" id=\"p\"><h2>Simple, honest pricing<\/h2><div class=\"sub\">Start free. Upgrade when you grow.<\/div>\n    <div class=\"toggle\"><span>Monthly<\/span><div class=\"sw ${yearly ? \"on\" : \"\"}\" id=\"sw\"><\/div><span>Yearly <span class=\"save\">save 20%<\/span><\/span><\/div>\n    <div class=\"grid\">${plans.map(p => {\n      const price = yearly ? Math.round(p.monthly * 0.8) : p.monthly;\n      return `<div class=\"card plan ${p.hot ? \"hot\" : \"\"}\"><h3>${p.name}<\/h3><p>${p.blurb}<\/p><div class=\"price\">${money(price)}<small> /mo<\/small><\/div>\n      <ul>${p.perks.map(x => `<li>${x}<\/li>`).join(\"\")}<\/ul><a class=\"btn ${p.hot ? \"p\" : \"\"}\" href=\"#\">${p.monthly ? \"Choose \" + p.name : \"Get started\"}<\/a><\/div>`;\n    }).join(\"\")}<\/div><\/section>\n  <section class=\"cta\"><h2>Your next deploy is 12 seconds away<\/h2><p>Join 40,000 teams shipping with Nimbus.<\/p><a class=\"btn p\" href=\"#\">Create free account<\/a><\/section>\n  <footer><span>© 2026 Nimbus Cloud, Inc.<\/span><span>Privacy · Terms · Status<\/span><\/footer><\/div>`;\n}\n\nconst root = document.getElementById(\"app\")!;\nroot.style.pointerEvents = \"auto\";\nfunction paint(): void {\n  const scroll = root.scrollTop;\n  root.innerHTML = render();\n  root.scrollTop = scroll;\n  document.getElementById(\"sw\")!.addEventListener(\"click\", () => { yearly = !yearly; console.log(\"billing:\", yearly ? \"yearly\" : \"monthly\"); paint(); });\n  root.querySelectorAll('a[href^=\"#\"]').forEach(a => a.addEventListener(\"click\", e => {\n    e.preventDefault();\n    const id = (a as HTMLAnchorElement).getAttribute(\"href\")!.slice(1);\n    if (id) document.getElementById(id)?.scrollIntoView({ behavior: \"smooth\" });\n  }));\n}\npaint();\nconsole.log(\"landing page rendered:\", features.length, \"features,\", plans.length, \"plans\");\n", "Page: social media feed": "// A mini social network page: compose, like, repost, reply, follow, filter. All state is in memory.\n\ninterface Author { handle: string; name: string; color: string; bio: string }\ninterface Post { id: number; by: string; text: string; time: string; likes: number; reposts: number; replies: string[]; liked: boolean; tag: string }\n\nconst authors: Record<string, Author> = {\n  ada:   { handle: \"ada\",   name: \"Ada Lovelace\",  color: \"#a78bfa\", bio: \"First programmer. Analytical Engine fan.\" },\n  linus: { handle: \"linus\", name: \"Linus T.\",      color: \"#34d399\", bio: \"Kernel hacker. Opinions: strong.\" },\n  grace: { handle: \"grace\", name: \"Grace Hopper\",  color: \"#f59e0b\", bio: \"Found the first bug. Taped it in the log.\" },\n  you:   { handle: \"you\",   name: \"You\",           color: \"#60a5fa\", bio: \"Learning in public with DevPortal.\" },\n};\nlet nextId = 5;\nlet posts: Post[] = [\n  { id: 4, by: \"grace\", text: \"Reminder: the most dangerous phrase in computing is “we've always done it this way”. 🪲\", time: \"2m\", likes: 128, reposts: 31, replies: [], liked: false, tag: \"career\" },\n  { id: 3, by: \"linus\", text: \"Talk is cheap. Show me the (compiling) code. Also: please run the tests before pushing.\", time: \"18m\", likes: 342, reposts: 77, replies: [\"ada: Tests first, then talk. 😄\"], liked: false, tag: \"code\" },\n  { id: 2, by: \"ada\",   text: \"Today I taught a loom to compute Bernoulli numbers. The poetry of programming is that it weaves thought. ✨\", time: \"1h\", likes: 509, reposts: 120, replies: [], liked: true, tag: \"history\" },\n  { id: 1, by: \"you\",   text: \"Hello DevPortal! My first post from the TypeScript playground. 👋\", time: \"3h\", likes: 12, reposts: 1, replies: [], liked: false, tag: \"code\" },\n];\nconst following = new Set<string>([\"ada\"]);\nlet filter = \"all\";\nconst tags = [\"all\", \"code\", \"career\", \"history\"];\n\nconst css = `\n.sn{font:15px/1.45 system-ui,-apple-system,Segoe UI,sans-serif;color:#e7e9ee;background:#0f1419;min-height:100%}\n.sn .wrap{max-width:980px;margin:0 auto;display:grid;grid-template-columns:200px 1fr 260px;gap:0}\n.sn aside{padding:16px 12px;position:sticky;top:0;align-self:start}\n.sn .brand{font-size:24px;font-weight:800;padding:6px 12px 14px;color:#60a5fa}\n.sn .nav a{display:block;padding:11px 14px;border-radius:99px;font-size:17px;cursor:pointer;color:#e7e9ee}\n.sn .nav a.on{font-weight:700;background:#1d2733}.sn .nav a:hover{background:#192330}\n.sn main{border-left:1px solid #2f3640;border-right:1px solid #2f3640;min-height:100vh}\n.sn header{position:sticky;top:0;background:#0f1419ee;backdrop-filter:blur(8px);padding:14px 16px;font-weight:700;font-size:19px;border-bottom:1px solid #2f3640;z-index:2}\n.av{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;font-weight:700;color:#0f1419;flex:none}\n.comp{display:flex;gap:12px;padding:14px 16px;border-bottom:1px solid #2f3640}\n.comp textarea{flex:1;background:transparent;border:0;outline:0;color:inherit;font:inherit;resize:none;min-height:56px}\n.comp .bar{display:flex;justify-content:space-between;align-items:center;color:#71767b;font-size:13px}\n.post{display:flex;gap:12px;padding:14px 16px;border-bottom:1px solid #2f3640}\n.post:hover{background:#131a22}.post .b{flex:1;min-width:0}\n.post .n{font-weight:700}.post .m{color:#71767b}\n.post .t{margin:2px 0 8px;white-space:pre-wrap;word-wrap:break-word}\n.tag{color:#60a5fa;font-size:12px}\n.acts{display:flex;gap:30px;color:#71767b;font-size:13px}\n.acts button{background:none;border:0;color:inherit;cursor:pointer;font:inherit;padding:4px 0}\n.acts button:hover{color:#60a5fa}.acts .like.on{color:#f43f5e}\n.reply{margin-top:8px;padding:8px 12px;border-left:2px solid #2f3640;color:#a0a6ad;font-size:13px}\n.btn{background:#60a5fa;color:#0f1419;border:0;border-radius:99px;padding:8px 18px;font-weight:700;cursor:pointer}\n.btn:disabled{opacity:.4;cursor:default}\n.tabs{display:flex;border-bottom:1px solid #2f3640}.tabs a{flex:1;text-align:center;padding:13px;cursor:pointer;color:#71767b;font-weight:600}\n.tabs a.on{color:#e7e9ee;box-shadow:inset 0 -3px #60a5fa}\n.box{background:#16202a;border-radius:16px;padding:14px;margin-bottom:14px}.box h4{margin:0 0 10px;font-size:18px}\n.sug{display:flex;gap:10px;align-items:center;padding:8px 0}.sug .who{flex:1;min-width:0}.sug small{color:#71767b;display:block}\n.fol{background:transparent;border:1px solid #536471;color:#e7e9ee;border-radius:99px;padding:6px 14px;font-weight:600;cursor:pointer}\n.fol.on{background:#e7e9ee;color:#0f1419}\n@media(max-width:760px){.sn .wrap{grid-template-columns:1fr}.sn aside{display:none}}\n`;\nconst esc = (s: string) => s.replace(/[&<>\"]/g, c => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\" }[c]!));\nconst avatar = (a: Author) => `<div class=\"av\" style=\"background:${a.color}\">${a.name[0]}<\/div>`;\n\nconst app = document.getElementById(\"app\")!;\napp.style.pointerEvents = \"auto\";\nlet draft = \"\";\n\nfunction postHtml(p: Post): string {\n  const a = authors[p.by];\n  return `<article class=\"post\" data-id=\"${p.id}\">${avatar(a)}<div class=\"b\">\n    <div><span class=\"n\">${a.name}<\/span> <span class=\"m\">@${a.handle} · ${p.time}<\/span><\/div>\n    <div class=\"t\">${esc(p.text)}<\/div><span class=\"tag\">#${p.tag}<\/span>\n    <div class=\"acts\"><button data-a=\"reply\">💬 ${p.replies.length}<\/button><button data-a=\"repost\">🔁 ${p.reposts}<\/button><button data-a=\"like\" class=\"like ${p.liked ? \"on\" : \"\"}\">${p.liked ? \"❤️\" : \"🤍\"} ${p.likes}<\/button><\/div>\n    ${p.replies.map(r => `<div class=\"reply\">${esc(r)}<\/div>`).join(\"\")}<\/div><\/article>`;\n}\nfunction view(): void {\n  const list = posts.filter(p => filter === \"all\" || p.tag === filter);\n  const sug = Object.values(authors).filter(a => a.handle !== \"you\");\n  app.innerHTML = `<style>${css}<\/style><div class=\"sn\"><div class=\"wrap\">\n  <aside><div class=\"brand\">◉ Chirp<\/div><div class=\"nav\"><a class=\"on\">🏠 Home<\/a><a>🔎 Explore<\/a><a>🔔 Notifications<\/a><a>✉️ Messages<\/a><a>👤 Profile<\/a><\/div><\/aside>\n  <main><header>Home<\/header>\n    <div class=\"comp\">${avatar(authors.you)}<div style=\"flex:1\"><textarea id=\"draft\" maxlength=\"140\" placeholder=\"What is happening?!\">${esc(draft)}<\/textarea>\n      <div class=\"bar\"><span id=\"cnt\">${140 - draft.length}<\/span><button class=\"btn\" id=\"send\" ${draft.trim() ? \"\" : \"disabled\"}>Chirp<\/button><\/div><\/div><\/div>\n    <div class=\"tabs\">${tags.map(t => `<a data-f=\"${t}\" class=\"${filter === t ? \"on\" : \"\"}\">${t === \"all\" ? \"For you\" : \"#\" + t}<\/a>`).join(\"\")}<\/div>\n    ${list.length ? list.map(postHtml).join(\"\") : '<p style=\"padding:30px;text-align:center;color:#71767b\">Nothing here yet.<\/p>'}<\/main>\n  <aside><div class=\"box\"><h4>Who to follow<\/h4>${sug.map(a => `<div class=\"sug\">${avatar(a)}<div class=\"who\"><b>${a.name}<\/b><small>${esc(a.bio)}<\/small><\/div>\n    <button class=\"fol ${following.has(a.handle) ? \"on\" : \"\"}\" data-u=\"${a.handle}\">${following.has(a.handle) ? \"Following\" : \"Follow\"}<\/button><\/div>`).join(\"\")}<\/div>\n  <div class=\"box\"><h4>Trending<\/h4><div class=\"sug\"><div class=\"who\"><b>#TypeScript<\/b><small>12.4K chirps<\/small><\/div><\/div><div class=\"sug\"><div class=\"who\"><b>#DevPortal<\/b><small>Trending in Tech<\/small><\/div><\/div><\/div><\/aside>\n  <\/div><\/div>`;\n  const ta = document.getElementById(\"draft\") as HTMLTextAreaElement;\n  ta.addEventListener(\"input\", () => { draft = ta.value; document.getElementById(\"cnt\")!.textContent = String(140 - draft.length); (document.getElementById(\"send\") as HTMLButtonElement).disabled = !draft.trim(); });\n  document.getElementById(\"send\")!.addEventListener(\"click\", () => {\n    const text = draft.trim(); if (!text) return;\n    const tag = (text.match(/#(\\w+)/) || [, \"code\"])[1]!.toLowerCase();\n    if (!tags.includes(tag)) tags.push(tag);\n    posts.unshift({ id: nextId++, by: \"you\", text, time: \"now\", likes: 0, reposts: 0, replies: [], liked: false, tag });\n    draft = \"\"; console.log(\"posted:\", text); view();\n  });\n  app.querySelectorAll<HTMLElement>(\"[data-f]\").forEach(el => el.addEventListener(\"click\", () => { filter = el.dataset.f!; view(); }));\n  app.querySelectorAll<HTMLElement>(\"[data-u]\").forEach(el => el.addEventListener(\"click\", () => {\n    const u = el.dataset.u!; following.has(u) ? following.delete(u) : following.add(u);\n    console.log(\"following:\", [...following].join(\", \") || \"nobody\"); view();\n  }));\n  app.querySelectorAll<HTMLElement>(\"article [data-a]\").forEach(el => el.addEventListener(\"click\", () => {\n    const id = Number(el.closest(\"article\")!.getAttribute(\"data-id\")); const p = posts.find(x => x.id === id)!;\n    switch (el.dataset.a) {\n      case \"like\": p.liked = !p.liked; p.likes += p.liked ? 1 : -1; break;\n      case \"repost\": p.reposts++; console.log(\"reposted\", id); break;\n      case \"reply\": p.replies.push(\"you: Great point!\"); break;\n    }\n    view();\n  }));\n}\nview();\nconsole.log(\"feed ready:\", posts.length, \"posts\");\n", "Page: stock market dashboard": "// A live stock-market dashboard with simulated prices. Pick a ticker to see its chart.\n// (Prices are a random walk — pure fiction, great for practice.)\n\ninterface Stock { sym: string; name: string; price: number; open: number; hist: number[]; vol: number }\nconst mk = (sym: string, name: string, p: number, vol: number): Stock => ({ sym, name, price: p, open: p, vol, hist: Array.from({ length: 60 }, () => p) });\nconst stocks: Stock[] = [\n  mk(\"NVDA\", \"Nvidia Corp\", 912.4, 0.012), mk(\"AAPL\", \"Apple Inc\", 189.3, 0.006), mk(\"MSFT\", \"Microsoft\", 421.8, 0.006),\n  mk(\"TSLA\", \"Tesla Inc\", 176.2, 0.014), mk(\"AMZN\", \"Amazon.com\", 183.5, 0.008), mk(\"GOOG\", \"Alphabet\", 164.9, 0.007),\n  mk(\"META\", \"Meta Platforms\", 502.6, 0.009), mk(\"NFLX\", \"Netflix\", 611.0, 0.01),\n];\nconst indices = [{ n: \"S&P 500\", v: 5234.2, o: 5234.2 }, { n: \"NASDAQ\", v: 16410.5, o: 16410.5 }, { n: \"DOW\", v: 39127.1, o: 39127.1 }];\nlet sel = \"NVDA\"; let paused = false; let tick = 0;\n\nconst app = document.getElementById(\"app\")!;\napp.style.pointerEvents = \"auto\";\nconst css = `\n.mk{font:14px/1.4 system-ui,-apple-system,Segoe UI,sans-serif;background:#0b0f14;color:#dbe2ea;min-height:100%;padding:16px}\n.mk h1{font-size:18px;margin:0;display:flex;align-items:center;gap:10px}.dot{width:9px;height:9px;border-radius:50%;background:#22c55e;box-shadow:0 0 10px #22c55e;animation:p 1.2s infinite}\n@keyframes p{50%{opacity:.3}}\n.mk .top{display:flex;gap:12px;align-items:center;justify-content:space-between;margin-bottom:14px;flex-wrap:wrap}\n.idx{display:flex;gap:10px;flex-wrap:wrap}.idx div{background:#121922;border:1px solid #1e2935;border-radius:10px;padding:8px 14px;min-width:130px}\n.idx small{color:#7d8a99;display:block}\n.up{color:#22c55e}.dn{color:#ef4444}\n.cols{display:grid;grid-template-columns:minmax(300px,1.1fr) 1.4fr;gap:14px}\n@media(max-width:820px){.cols{grid-template-columns:1fr}}\n.card{background:#121922;border:1px solid #1e2935;border-radius:12px;overflow:hidden}\ntable{width:100%;border-collapse:collapse}th{font-weight:600;color:#7d8a99;font-size:12px;text-align:right;padding:9px 12px;border-bottom:1px solid #1e2935}\nth:first-child,td:first-child{text-align:left}td{padding:9px 12px;text-align:right;border-bottom:1px solid #18212c;font-variant-numeric:tabular-nums}\ntr.row{cursor:pointer}tr.row:hover{background:#17212d}tr.sel{background:#1b2838!important}\ntd b{display:block;color:#fff}td small{color:#7d8a99}\n.chart{padding:14px}.chart .big{font-size:32px;font-weight:700;font-variant-numeric:tabular-nums}\n.chart .sub{color:#7d8a99;margin-bottom:8px}\n.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:10px}.stats div{background:#0e141b;border-radius:8px;padding:8px 10px}.stats small{color:#7d8a99;display:block}\nbutton{background:#1b2838;color:#dbe2ea;border:1px solid #2a3a4e;border-radius:8px;padding:7px 12px;cursor:pointer}button:hover{background:#243348}\n.mv{display:flex;gap:10px;margin-top:14px}.mv .card{flex:1;padding:12px}.mv h3{margin:0 0 8px;font-size:13px;color:#7d8a99}.mv div.l{display:flex;justify-content:space-between;padding:3px 0}\n`;\nconst f2 = (n: number) => n.toLocaleString(\"en-US\", { minimumFractionDigits: 2, maximumFractionDigits: 2 });\nconst pct = (s: Stock) => ((s.price - s.open) / s.open) * 100;\nconst cls = (n: number) => (n >= 0 ? \"up\" : \"dn\");\nconst sgn = (n: number) => (n >= 0 ? \"+\" : \"\") + f2(n);\n\nfunction spark(h: number[], w = 90, ht = 26): string {\n  const lo = Math.min(...h), hi = Math.max(...h), rng = hi - lo || 1;\n  const pts = h.map((v, i) => (i / (h.length - 1) * w).toFixed(1) + \",\" + (ht - ((v - lo) / rng) * (ht - 2) - 1).toFixed(1)).join(\" \");\n  const c = h[h.length - 1] >= h[0] ? \"#22c55e\" : \"#ef4444\";\n  return `<svg width=\"${w}\" height=\"${ht}\"><polyline fill=\"none\" stroke=\"${c}\" stroke-width=\"1.6\" points=\"${pts}\"/><\/svg>`;\n}\nfunction bigChart(s: Stock): string {\n  const W = 640, H = 220, lo = Math.min(...s.hist) * 0.999, hi = Math.max(...s.hist) * 1.001, rng = hi - lo || 1;\n  const x = (i: number) => (i / (s.hist.length - 1)) * W, y = (v: number) => H - ((v - lo) / rng) * (H - 10) - 5;\n  const line = s.hist.map((v, i) => x(i).toFixed(1) + \",\" + y(v).toFixed(1)).join(\" \");\n  const c = s.price >= s.open ? \"#22c55e\" : \"#ef4444\";\n  const grid = [0, 1, 2, 3].map(i => `<line x1=\"0\" x2=\"${W}\" y1=\"${(i * H) / 3 + 1}\" y2=\"${(i * H) / 3 + 1}\" stroke=\"#1e2935\"/>`).join(\"\");\n  return `<svg viewBox=\"0 0 ${W} ${H}\" style=\"width:100%;height:auto\">${grid}<polygon fill=\"${c}22\" points=\"0,${H} ${line} ${W},${H}\"/><polyline fill=\"none\" stroke=\"${c}\" stroke-width=\"2\" points=\"${line}\"/>\n  <circle cx=\"${W}\" cy=\"${y(s.price).toFixed(1)}\" r=\"4\" fill=\"${c}\"/><\/svg>`;\n}\nfunction step(): void {\n  tick++;\n  for (const s of stocks) {\n    const drift = (Math.random() - 0.495) * s.vol;\n    s.price = Math.max(1, s.price * (1 + drift)); s.hist.push(s.price); if (s.hist.length > 60) s.hist.shift();\n  }\n  for (const i of indices) i.v *= 1 + (Math.random() - 0.495) * 0.0012;\n}\nfunction view(): void {\n  const s = stocks.find(x => x.sym === sel)!;\n  const sorted = [...stocks].sort((a, b) => pct(b) - pct(a));\n  app.innerHTML = `<style>${css}<\/style><div class=\"mk\"><div class=\"top\"><h1><span class=\"dot\"><\/span>MarketWatch <small style=\"color:#7d8a99;font-weight:400\">simulated · tick ${tick}<\/small><\/h1>\n    <div><button id=\"pz\">${paused ? \"▶ Resume\" : \"⏸ Pause\"}<\/button><\/div><\/div>\n    <div class=\"idx\">${indices.map(i => { const c = ((i.v - i.o) / i.o) * 100; return `<div><small>${i.n}<\/small><b>${f2(i.v)}<\/b> <span class=\"${cls(c)}\">${sgn(c)}%<\/span><\/div>`; }).join(\"\")}<\/div>\n    <div class=\"cols\" style=\"margin-top:14px\"><div class=\"card\"><table><thead><tr><th>Symbol<\/th><th>Last<\/th><th>Chg %<\/th><th>Trend<\/th><\/tr><\/thead><tbody>\n    ${stocks.map(t => `<tr class=\"row ${t.sym === sel ? \"sel\" : \"\"}\" data-s=\"${t.sym}\"><td><b>${t.sym}<\/b><small>${t.name}<\/small><\/td><td>${f2(t.price)}<\/td><td class=\"${cls(pct(t))}\">${sgn(pct(t))}%<\/td><td>${spark(t.hist)}<\/td><\/tr>`).join(\"\")}\n    <\/tbody><\/table><\/div>\n    <div class=\"card chart\"><div><b>${s.sym}<\/b> <span style=\"color:#7d8a99\">${s.name}<\/span><\/div><div class=\"big\">$${f2(s.price)} <span class=\"${cls(pct(s))}\" style=\"font-size:16px\">${sgn(s.price - s.open)} (${sgn(pct(s))}%)<\/span><\/div>\n    <div class=\"sub\">Last 60 ticks<\/div>${bigChart(s)}\n    <div class=\"stats\"><div><small>Open<\/small>${f2(s.open)}<\/div><div><small>High<\/small>${f2(Math.max(...s.hist))}<\/div><div><small>Low<\/small>${f2(Math.min(...s.hist))}<\/div><div><small>Volatility<\/small>${(s.vol * 100).toFixed(1)}%<\/div><\/div><\/div><\/div>\n    <div class=\"mv\"><div class=\"card\"><h3>TOP GAINERS<\/h3>${sorted.slice(0, 3).map(t => `<div class=\"l\"><b>${t.sym}<\/b><span class=\"up\">${sgn(pct(t))}%<\/span><\/div>`).join(\"\")}<\/div>\n    <div class=\"card\"><h3>TOP LOSERS<\/h3>${sorted.slice(-3).reverse().map(t => `<div class=\"l\"><b>${t.sym}<\/b><span class=\"dn\">${sgn(pct(t))}%<\/span><\/div>`).join(\"\")}<\/div><\/div><\/div>`;\n  app.querySelectorAll<HTMLElement>(\"tr[data-s]\").forEach(r => r.addEventListener(\"click\", () => { sel = r.dataset.s!; console.log(\"selected\", sel); view(); }));\n  document.getElementById(\"pz\")!.addEventListener(\"click\", () => { paused = !paused; view(); });\n}\nfor (let i = 0; i < 40; i++) step();               // warm up so charts start with some history\nview();\nsetInterval(() => { if (!paused) { step(); view(); } }, 900);\nconsole.log(\"market open — click a row to change the chart\");\n", "Async + discriminated unions": "// Async + discriminated unions — the compiler narrows each branch for you.\n// Results are logged to the Console AND drawn in the preview.\n\ntype Loading = { status: \"loading\" };\ntype Success<T> = { status: \"success\"; data: T; ms: number };\ntype Failure = { status: \"error\"; error: string; retryable: boolean };\ntype Result<T> = Loading | Success<T> | Failure;\n\ninterface User { id: number; name: string; role: \"admin\" | \"editor\" | \"viewer\" }\n\nconst wait = (ms: number) => new Promise<void>(r => setTimeout(r, ms));\n\nasync function fetchUser(id: number): Promise<Result<User>> {\n  const t0 = Date.now();\n  await wait(250 + Math.random() * 350);                 // pretend network\n  if (id === 13) return { status: \"error\", error: \"Unlucky number: server said 500\", retryable: true };\n  if (id > 20) return { status: \"error\", error: \"User \" + id + \" not found\", retryable: false };\n  const roles: User[\"role\"][] = [\"admin\", \"editor\", \"viewer\"];\n  return { status: \"success\", ms: Date.now() - t0, data: { id, name: \"User #\" + id, role: roles[id % 3] } };\n}\n\nfunction describe(r: Result<User>): string {\n  switch (r.status) {                                    // exhaustive switch: add a case and TS complains\n    case \"loading\": return \"⏳ loading…\";\n    case \"success\": return \"✅ \" + r.data.name + \" (\" + r.data.role + \") in \" + r.ms + \"ms\";\n    case \"error\":   return \"❌ \" + r.error + (r.retryable ? \"  — will retry\" : \"\");\n  }\n}\n\n// ---- tiny UI -------------------------------------------------------------\nconst app = document.getElementById(\"app\")!;\napp.style.pointerEvents = \"auto\";\napp.innerHTML = `<style>\n  .box{max-width:560px;margin:28px auto;font:14px/1.5 system-ui,sans-serif;color:${THEME.fg}}\n  h2{margin:0 0 4px;color:${THEME.accent}} p{margin:0 0 14px;color:${THEME.muted}}\n  .row{display:flex;gap:10px;align-items:center;padding:10px 12px;margin:6px 0;border:1px solid ${THEME.muted}55;border-radius:10px;background:${THEME.bg}}\n  .row b{min-width:58px} .ok{border-color:${THEME.ok}} .bad{border-color:${THEME.err}} .wait{opacity:.7}\n  button{margin-top:10px;padding:8px 14px;border-radius:8px;border:0;background:${THEME.accent};color:#fff;cursor:pointer;font-weight:600}\n<\/style><div class=\"box\"><h2>Async + discriminated unions<\/h2><p>Each row is a <code>Result&lt;User&gt;<\/code>. Try the button to run it again.<\/p><div id=\"rows\"><\/div><button id=\"again\">Run again<\/button><\/div>`;\n\nconst rows = document.getElementById(\"rows\")!;\nasync function load(ids: number[]) {\n  rows.innerHTML = \"\";\n  const els = ids.map(id => {\n    const d = document.createElement(\"div\");\n    d.className = \"row wait\"; d.innerHTML = \"<b>id \" + id + \"<\/b><span>\" + describe({ status: \"loading\" }) + \"<\/span>\";\n    rows.appendChild(d); return d;\n  });\n  const results = await Promise.all(ids.map(fetchUser));\n  results.forEach((r, i) => {\n    els[i].className = \"row \" + (r.status === \"success\" ? \"ok\" : \"bad\");\n    els[i].lastElementChild!.textContent = describe(r);\n    console.log(\"id\", ids[i], \"→\", describe(r));\n  });\n  const okCount = results.filter(r => r.status === \"success\").length;\n  console.log(okCount + \" of \" + results.length + \" succeeded\");\n}\ndocument.getElementById(\"again\")!.addEventListener(\"click\", () => load([1, 2, 13, 42, 7]));\nload([1, 2, 13, 42, 7]);\n"}, "groups": {"Pages": ["Page: tech landing (Nimbus)", "Page: social media feed", "Page: stock market dashboard"], "Basics": ["Async + discriminated unions"]}}, "rust": {"examples": {"NES: 6502 CPU emulator": "// A tiny NES-style CPU: MOS 6502 subset + mini assembler + a 32x32 \"screen\" at $0200.\n// (Same idea as the famous easy6502 playground. No ROMs, no Nintendo code — just the CPU idea.)\nuse std::collections::HashMap;\n\nconst C: u8 = 0x01;\nconst Z: u8 = 0x02;\nconst N: u8 = 0x80;\n\nstruct Cpu {\n    a: u8,\n    x: u8,\n    y: u8,\n    sp: u8,\n    pc: u16,\n    p: u8,\n    mem: Vec<u8>,\n    cycles: u64,\n    halted: bool,\n}\n\nimpl Cpu {\n    fn new() -> Self {\n        Cpu { a: 0, x: 0, y: 0, sp: 0xFF, pc: 0x0600, p: 0x20, mem: vec![0; 65536], cycles: 0, halted: false }\n    }\n    fn rd(&self, addr: u16) -> u8 { self.mem[addr as usize] }\n    fn wr(&mut self, addr: u16, v: u8) { self.mem[addr as usize] = v; }\n    fn fetch(&mut self) -> u8 {\n        let v = self.rd(self.pc);\n        self.pc = self.pc.wrapping_add(1);\n        v\n    }\n    fn fetch16(&mut self) -> u16 {\n        let lo = self.fetch() as u16;\n        let hi = self.fetch() as u16;\n        (hi << 8) | lo\n    }\n    fn set_zn(&mut self, v: u8) {\n        self.p = (self.p & !(Z | N)) | if v == 0 { Z } else { 0 } | (v & N);\n    }\n    fn push(&mut self, v: u8) { let a = 0x0100 + self.sp as u16; self.wr(a, v); self.sp = self.sp.wrapping_sub(1); }\n    fn pull(&mut self) -> u8 { self.sp = self.sp.wrapping_add(1); self.rd(0x0100 + self.sp as u16) }\n    fn branch(&mut self, cond: bool) {\n        let off = self.fetch() as i8;\n        if cond { self.pc = self.pc.wrapping_add(off as i16 as u16); self.cycles += 1; }\n    }\n    fn compare(&mut self, reg: u8, v: u8) {\n        self.p = if reg >= v { self.p | C } else { self.p & !C };\n        self.set_zn(reg.wrapping_sub(v));\n    }\n    fn adc(&mut self, v: u8) {\n        let sum = self.a as u16 + v as u16 + (self.p & C) as u16;\n        self.p = if sum > 0xFF { self.p | C } else { self.p & !C };\n        self.a = sum as u8;\n        let a = self.a;\n        self.set_zn(a);\n    }\n\n    fn step(&mut self) -> String {\n        let at = self.pc;\n        let op = self.fetch();\n        let name: &str;\n        match op {\n            0x00 => { name = \"BRK\"; self.halted = true; }\n            0xEA => { name = \"NOP\"; }\n            0xA9 => { name = \"LDA #\"; let v = self.fetch(); self.a = v; self.set_zn(v); }\n            0xA5 => { name = \"LDA zp\"; let z = self.fetch() as u16; let v = self.rd(z); self.a = v; self.set_zn(v); }\n            0xAD => { name = \"LDA abs\"; let ad = self.fetch16(); let v = self.rd(ad); self.a = v; self.set_zn(v); }\n            0xBD => { name = \"LDA abs,X\"; let ad = self.fetch16().wrapping_add(self.x as u16); let v = self.rd(ad); self.a = v; self.set_zn(v); }\n            0xA2 => { name = \"LDX #\"; let v = self.fetch(); self.x = v; self.set_zn(v); }\n            0xA0 => { name = \"LDY #\"; let v = self.fetch(); self.y = v; self.set_zn(v); }\n            0x85 => { name = \"STA zp\"; let z = self.fetch() as u16; let a = self.a; self.wr(z, a); }\n            0x86 => { name = \"STX zp\"; let z = self.fetch() as u16; let x = self.x; self.wr(z, x); }\n            0x8D => { name = \"STA abs\"; let ad = self.fetch16(); let a = self.a; self.wr(ad, a); }\n            0x9D => { name = \"STA abs,X\"; let ad = self.fetch16().wrapping_add(self.x as u16); let a = self.a; self.wr(ad, a); }\n            0x99 => { name = \"STA abs,Y\"; let ad = self.fetch16().wrapping_add(self.y as u16); let a = self.a; self.wr(ad, a); }\n            0xAA => { name = \"TAX\"; self.x = self.a; let v = self.x; self.set_zn(v); }\n            0x8A => { name = \"TXA\"; self.a = self.x; let v = self.a; self.set_zn(v); }\n            0xA8 => { name = \"TAY\"; self.y = self.a; let v = self.y; self.set_zn(v); }\n            0x98 => { name = \"TYA\"; self.a = self.y; let v = self.a; self.set_zn(v); }\n            0xE8 => { name = \"INX\"; self.x = self.x.wrapping_add(1); let v = self.x; self.set_zn(v); }\n            0xC8 => { name = \"INY\"; self.y = self.y.wrapping_add(1); let v = self.y; self.set_zn(v); }\n            0xCA => { name = \"DEX\"; self.x = self.x.wrapping_sub(1); let v = self.x; self.set_zn(v); }\n            0x88 => { name = \"DEY\"; self.y = self.y.wrapping_sub(1); let v = self.y; self.set_zn(v); }\n            0x69 => { name = \"ADC #\"; let v = self.fetch(); self.adc(v); }\n            0x65 => { name = \"ADC zp\"; let z = self.fetch() as u16; let v = self.rd(z); self.adc(v); }\n            0x29 => { name = \"AND #\"; let v = self.fetch(); self.a &= v; let r = self.a; self.set_zn(r); }\n            0x09 => { name = \"ORA #\"; let v = self.fetch(); self.a |= v; let r = self.a; self.set_zn(r); }\n            0x49 => { name = \"EOR #\"; let v = self.fetch(); self.a ^= v; let r = self.a; self.set_zn(r); }\n            0x0A => { name = \"ASL A\"; let c = self.a >> 7; self.a <<= 1; self.p = (self.p & !C) | c; let r = self.a; self.set_zn(r); }\n            0x4A => { name = \"LSR A\"; let c = self.a & 1; self.a >>= 1; self.p = (self.p & !C) | c; let r = self.a; self.set_zn(r); }\n            0x18 => { name = \"CLC\"; self.p &= !C; }\n            0x38 => { name = \"SEC\"; self.p |= C; }\n            0xC9 => { name = \"CMP #\"; let v = self.fetch(); let a = self.a; self.compare(a, v); }\n            0xE0 => { name = \"CPX #\"; let v = self.fetch(); let x = self.x; self.compare(x, v); }\n            0xC0 => { name = \"CPY #\"; let v = self.fetch(); let y = self.y; self.compare(y, v); }\n            0xD0 => { name = \"BNE\"; let c = self.p & Z == 0; self.branch(c); }\n            0xF0 => { name = \"BEQ\"; let c = self.p & Z != 0; self.branch(c); }\n            0x90 => { name = \"BCC\"; let c = self.p & C == 0; self.branch(c); }\n            0xB0 => { name = \"BCS\"; let c = self.p & C != 0; self.branch(c); }\n            0x4C => { name = \"JMP\"; self.pc = self.fetch16(); }\n            0x20 => { name = \"JSR\"; let ad = self.fetch16(); let ret = self.pc.wrapping_sub(1); self.push((ret >> 8) as u8); self.push(ret as u8); self.pc = ad; }\n            0x60 => { name = \"RTS\"; let lo = self.pull() as u16; let hi = self.pull() as u16; self.pc = ((hi << 8) | lo).wrapping_add(1); }\n            0x48 => { name = \"PHA\"; let a = self.a; self.push(a); }\n            0x68 => { name = \"PLA\"; let v = self.pull(); self.a = v; self.set_zn(v); }\n            _ => { name = \"???\"; self.halted = true; }\n        }\n        self.cycles += 2;\n        format!(\"{:04X}  {:02X}  {:<10} A={:02X} X={:02X} Y={:02X} P={:08b}\", at, op, name, self.a, self.x, self.y, self.p)\n    }\n}\n\n// ---- mini assembler -------------------------------------------------------\nfn num(s: &str) -> u16 {\n    let s = s.trim_start_matches('#');\n    if let Some(h) = s.strip_prefix('$') { u16::from_str_radix(h, 16).unwrap() } else { s.parse().unwrap() }\n}\n\nfn assemble(src: &str, org: u16) -> Vec<u8> {\n    let mut labels: HashMap<String, u16> = HashMap::new();\n    let mut lines: Vec<(String, String)> = Vec::new();\n    for raw in src.lines() {\n        let mut l = raw.split(';').next().unwrap().trim().to_string();\n        if l.is_empty() { continue; }\n        while let Some(i) = l.find(':') {\n            lines.push((l[..i].trim().to_string(), String::new()));\n            l = l[i + 1..].trim().to_string();\n        }\n        if !l.is_empty() { lines.push((String::new(), l)); }\n    }\n    for pass in 0..2 {\n        let mut out: Vec<u8> = Vec::new();\n        for (label, ins) in &lines {\n            let addr = org + out.len() as u16;\n            if !label.is_empty() { labels.insert(label.clone(), addr); continue; }\n            let mut it = ins.splitn(2, ' ');\n            let m = it.next().unwrap().to_uppercase();\n            let arg = it.next().unwrap_or(\"\").trim().to_string();\n            let imp = |op: u8, out: &mut Vec<u8>| out.push(op);\n            let rel = |op: u8, out: &mut Vec<u8>, labels: &HashMap<String, u16>| {\n                out.push(op);\n                let t = *labels.get(&arg).unwrap_or(&0) as i32;\n                out.push((t - (addr as i32 + 2)) as i8 as u8);\n            };\n            match m.as_str() {\n                \"BRK\" => imp(0x00, &mut out), \"NOP\" => imp(0xEA, &mut out), \"TAX\" => imp(0xAA, &mut out),\n                \"TXA\" => imp(0x8A, &mut out), \"TAY\" => imp(0xA8, &mut out), \"TYA\" => imp(0x98, &mut out),\n                \"INX\" => imp(0xE8, &mut out), \"INY\" => imp(0xC8, &mut out), \"DEX\" => imp(0xCA, &mut out),\n                \"DEY\" => imp(0x88, &mut out), \"CLC\" => imp(0x18, &mut out), \"SEC\" => imp(0x38, &mut out),\n                \"RTS\" => imp(0x60, &mut out), \"PHA\" => imp(0x48, &mut out), \"PLA\" => imp(0x68, &mut out),\n                \"ASL\" => imp(0x0A, &mut out), \"LSR\" => imp(0x4A, &mut out),\n                \"BNE\" => rel(0xD0, &mut out, &labels), \"BEQ\" => rel(0xF0, &mut out, &labels),\n                \"BCC\" => rel(0x90, &mut out, &labels), \"BCS\" => rel(0xB0, &mut out, &labels),\n                \"JMP\" | \"JSR\" => {\n                    out.push(if m == \"JMP\" { 0x4C } else { 0x20 });\n                    let t = *labels.get(&arg).unwrap_or(&0);\n                    out.push(t as u8); out.push((t >> 8) as u8);\n                }\n                _ => {\n                    if arg.starts_with('#') {\n                        let op = match m.as_str() { \"LDA\" => 0xA9, \"LDX\" => 0xA2, \"LDY\" => 0xA0, \"ADC\" => 0x69, \"AND\" => 0x29,\n                            \"ORA\" => 0x09, \"EOR\" => 0x49, \"CMP\" => 0xC9, \"CPX\" => 0xE0, \"CPY\" => 0xC0, _ => panic!(\"bad op {}\", m) };\n                        out.push(op); out.push(num(&arg) as u8);\n                    } else {\n                        let (base, idx) = match arg.split_once(',') { Some((b, i)) => (b.trim(), i.trim().to_uppercase()), None => (arg.as_str(), String::new()) };\n                        let v = num(base);\n                        let zp = v < 256 && idx.is_empty() && matches!(m.as_str(), \"LDA\" | \"STA\" | \"ADC\" | \"STX\");\n                        let op = match (m.as_str(), idx.as_str(), zp) {\n                            (\"LDA\", \"\", true) => 0xA5, (\"LDA\", \"\", false) => 0xAD, (\"LDA\", \"X\", _) => 0xBD,\n                            (\"STA\", \"\", true) => 0x85, (\"STA\", \"\", false) => 0x8D, (\"STA\", \"X\", _) => 0x9D, (\"STA\", \"Y\", _) => 0x99,\n                            (\"ADC\", \"\", true) => 0x65, (\"STX\", \"\", true) => 0x86, _ => panic!(\"unsupported {} {}\", m, arg) };\n                        out.push(op);\n                        out.push(v as u8);\n                        if !zp { out.push((v >> 8) as u8); }\n                    }\n                }\n            }\n        }\n        if pass == 1 { return out; }\n    }\n    unreachable!()\n}\n\nfn main() {\n    let program = \"\n        ; part 1: sum 1..10 into $10\n            LDX #10\n            LDA #0\n        add: STX $11\n            CLC\n            ADC $11\n            DEX\n            BNE add\n            STA $10\n        ; part 2: paint the 32x32 screen (colour = x & 15), then a bright diagonal\n            LDX #0\n        fill: TXA\n            AND #$0F\n            STA $0200,X\n            STA $0300,X\n            STA $0400,X\n            STA $0500,X\n            INX\n            BNE fill\n            LDX #0\n            LDY #0\n        diag: LDA #15\n            STA $0200,Y\n            TYA\n            CLC\n            ADC #33\n            TAY\n            INX\n            CPX #31\n            BNE diag\n            BRK\n    \";\n    let code = assemble(program, 0x0600);\n    println!(\"assembled {} bytes at $0600: {:02X?}\", code.len(), &code[..12.min(code.len())]);\n\n    let mut cpu = Cpu::new();\n    cpu.mem[0x0600..0x0600 + code.len()].copy_from_slice(&code);\n    let mut steps = 0;\n    while !cpu.halted && steps < 100_000 {\n        let line = cpu.step();\n        if steps < 8 { println!(\"{}\", line); }\n        steps += 1;\n    }\n    println!(\"...\\nhalted after {} instructions, ~{} cycles\", steps, cpu.cycles);\n    println!(\"sum(1..10) at $10 = {}\", cpu.mem[0x10]);\n\n    let shades: Vec<char> = \" .,:;ox%#@abcdef\".chars().collect();\n    println!(\"\\nscreen ($0200-$05FF):\");\n    for row in 0..32 {\n        let line: String = (0..32).map(|col| shades[(cpu.mem[0x0200 + row * 32 + col] & 15) as usize]).collect();\n        println!(\"|{}|\", line);\n    }\n}\n", "NES: tile / PPU renderer": "// NES-style graphics: the PPU stores each 8x8 tile as two bit-planes (16 bytes).\n// Combine plane 0 and plane 1 to get a 2-bit colour index per pixel — then map it to a palette.\n// The tile data below is original pixel art (a tiny heart + a smiling \"slime\").\nconst HEART: [u8; 16] = [\n    // plane 0 (low bit)\n    0b01100110, 0b11111111, 0b11111111, 0b11111111, 0b01111110, 0b00111100, 0b00011000, 0b00000000,\n    // plane 1 (high bit)\n    0b00000000, 0b01100110, 0b01011110, 0b01111110, 0b00111100, 0b00011000, 0b00000000, 0b00000000,\n];\nconst SLIME: [u8; 16] = [\n    0b00000000, 0b00111100, 0b01111110, 0b11111111, 0b11111111, 0b11111111, 0b11111111, 0b01111110,\n    0b00000000, 0b00000000, 0b00100100, 0b00100100, 0b00000000, 0b01000010, 0b00111100, 0b00000000,\n];\nconst GRASS: [u8; 16] = [\n    0b00000000, 0b01000100, 0b01010100, 0b11010101, 0b11111111, 0b11111111, 0b11111111, 0b11111111,\n    0b00000000, 0b00000000, 0b00000000, 0b00000000, 0b11111111, 0b11111111, 0b11111111, 0b11111111,\n];\n\n// Colour index (0..3) -> a character from the \"palette\"\nconst PALETTE: [&str; 4] = [\"  \", \"░░\", \"▒▒\", \"██\"];\n\nfn decode(tile: &[u8; 16]) -> [[u8; 8]; 8] {\n    let mut px = [[0u8; 8]; 8];\n    for row in 0..8 {\n        for col in 0..8 {\n            let bit = 7 - col;\n            let lo = (tile[row] >> bit) & 1;\n            let hi = (tile[row + 8] >> bit) & 1;\n            px[row][col] = (hi << 1) | lo;\n        }\n    }\n    px\n}\n\nfn main() {\n    let tiles = [(\"heart\", HEART), (\"slime\", SLIME), (\"grass\", GRASS)];\n    for (name, t) in tiles.iter() {\n        println!(\"tile '{}':\", name);\n        for row in decode(t).iter() {\n            println!(\"  {}\", row.iter().map(|&c| PALETTE[c as usize]).collect::<String>());\n        }\n    }\n\n    // A 12x6 \"nametable\": each cell is a tile index, like the NES background layer.\n    let map: [[usize; 12]; 6] = [\n        [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3],\n        [3, 0, 3, 3, 3, 3, 3, 3, 3, 3, 0, 3],\n        [3, 3, 3, 3, 3, 1, 3, 3, 3, 3, 3, 3],\n        [3, 3, 3, 3, 3, 3, 3, 3, 1, 3, 3, 3],\n        [2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2],\n        [2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2],\n    ];\n    let set = [decode(&HEART), decode(&SLIME), decode(&GRASS)];\n    println!(\"\\nbackground ({} x {} tiles = {} x {} pixels):\", 12, 6, 12 * 8, 6 * 8);\n    for ty in 0..6 {\n        for py in 0..8 {\n            let mut line = String::new();\n            for tx in 0..12 {\n                let idx = map[ty][tx];\n                if idx == 3 {\n                    line.push_str(&\"  \".repeat(8));\n                } else {\n                    for px in 0..8 {\n                        line.push_str(PALETTE[set[idx][py][px] as usize]);\n                    }\n                }\n            }\n            println!(\"{}\", line.trim_end());\n        }\n    }\n}\n", "Game of Life": "// Conway's Game of Life on a small wrapping grid, printed generation by generation.\nconst W: usize = 24;\nconst H: usize = 12;\n\n#[derive(Clone)]\nstruct Life {\n    cells: Vec<bool>,\n}\n\nimpl Life {\n    fn new() -> Self {\n        Life { cells: vec![false; W * H] }\n    }\n    fn set(&mut self, x: usize, y: usize) {\n        self.cells[y * W + x] = true;\n    }\n    fn neighbours(&self, x: usize, y: usize) -> usize {\n        let mut n = 0;\n        for dy in [H - 1, 0, 1] {\n            for dx in [W - 1, 0, 1] {\n                if dx == 0 && dy == 0 { continue; }\n                if self.cells[((y + dy) % H) * W + (x + dx) % W] { n += 1; }\n            }\n        }\n        n\n    }\n    fn step(&self) -> Life {\n        let mut next = Life::new();\n        for y in 0..H {\n            for x in 0..W {\n                let alive = self.cells[y * W + x];\n                let n = self.neighbours(x, y);\n                next.cells[y * W + x] = matches!((alive, n), (true, 2) | (true, 3) | (false, 3));\n            }\n        }\n        next\n    }\n    fn show(&self, gen: u32) {\n        println!(\"generation {} (alive: {})\", gen, self.cells.iter().filter(|&&c| c).count());\n        for y in 0..H {\n            let row: String = (0..W).map(|x| if self.cells[y * W + x] { '#' } else { '.' }).collect();\n            println!(\"{}\", row);\n        }\n        println!();\n    }\n}\n\nfn main() {\n    let mut life = Life::new();\n    // a glider\n    for &(x, y) in &[(1, 0), (2, 1), (0, 2), (1, 2), (2, 2)] { life.set(x, y); }\n    // a blinker\n    for &(x, y) in &[(15, 6), (16, 6), (17, 6)] { life.set(x, y); }\n    for gen in 0..5 {\n        life.show(gen);\n        life = life.step();\n    }\n}\n", "Tic-tac-toe AI": "// Tic-tac-toe with an unbeatable minimax AI. X (AI) plays against O (a scripted \"human\").\n#[derive(Clone, Copy, PartialEq)]\nenum Cell { Empty, X, O }\n\ntype Board = [Cell; 9];\n\nconst LINES: [[usize; 3]; 8] = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]];\n\nfn winner(b: &Board) -> Option<Cell> {\n    for l in LINES.iter() {\n        if b[l[0]] != Cell::Empty && b[l[0]] == b[l[1]] && b[l[1]] == b[l[2]] {\n            return Some(b[l[0]]);\n        }\n    }\n    None\n}\n\nfn full(b: &Board) -> bool { b.iter().all(|&c| c != Cell::Empty) }\n\nfn minimax(b: &mut Board, x_turn: bool, nodes: &mut u32) -> i32 {\n    *nodes += 1;\n    match winner(b) {\n        Some(Cell::X) => return 1,\n        Some(Cell::O) => return -1,\n        _ => {}\n    }\n    if full(b) { return 0; }\n    let mut best = if x_turn { -2 } else { 2 };\n    for i in 0..9 {\n        if b[i] == Cell::Empty {\n            b[i] = if x_turn { Cell::X } else { Cell::O };\n            let score = minimax(b, !x_turn, nodes);\n            b[i] = Cell::Empty;\n            best = if x_turn { best.max(score) } else { best.min(score) };\n        }\n    }\n    best\n}\n\nfn best_move(b: &mut Board, nodes: &mut u32) -> usize {\n    let mut best = (-2, 0);\n    for i in 0..9 {\n        if b[i] == Cell::Empty {\n            b[i] = Cell::X;\n            let s = minimax(b, false, nodes);\n            b[i] = Cell::Empty;\n            if s > best.0 { best = (s, i); }\n        }\n    }\n    best.1\n}\n\nfn show(b: &Board) {\n    for r in 0..3 {\n        let row: Vec<&str> = (0..3).map(|c| match b[r * 3 + c] { Cell::X => \"X\", Cell::O => \"O\", Cell::Empty => \".\" }).collect();\n        println!(\"  {}\", row.join(\" \"));\n    }\n    println!();\n}\n\nfn main() {\n    let mut b: Board = [Cell::Empty; 9];\n    let human_moves = [0usize, 5, 7, 2, 3];\n    let mut h = 0;\n    println!(\"AI = X, scripted opponent = O\\n\");\n    loop {\n        let mut nodes = 0;\n        let m = best_move(&mut b, &mut nodes);\n        b[m] = Cell::X;\n        println!(\"X plays {} (searched {} positions)\", m, nodes);\n        show(&b);\n        if winner(&b).is_some() || full(&b) { break; }\n        while h < human_moves.len() && b[human_moves[h]] != Cell::Empty { h += 1; }\n        let o = if h < human_moves.len() { human_moves[h] } else { (0..9).find(|&i| b[i] == Cell::Empty).unwrap() };\n        b[o] = Cell::O;\n        println!(\"O plays {}\", o);\n        show(&b);\n        if winner(&b).is_some() || full(&b) { break; }\n    }\n    match winner(&b) {\n        Some(Cell::X) => println!(\"X wins!\"),\n        Some(Cell::O) => println!(\"O wins!\"),\n        _ => println!(\"It's a draw.\"),\n    }\n}\n", "Brainfuck interpreter": "// A Brainfuck interpreter — a classic \"write a VM in an afternoon\" project.\nuse std::collections::HashMap;\n\nfn run(program: &str, max_steps: usize) -> Result<String, String> {\n    let code: Vec<char> = program.chars().filter(|c| \"+-<>[].,\".contains(*c)).collect();\n    // pre-compute matching brackets\n    let mut jump: HashMap<usize, usize> = HashMap::new();\n    let mut stack = Vec::new();\n    for (i, &c) in code.iter().enumerate() {\n        if c == '[' { stack.push(i); }\n        if c == ']' {\n            let open = stack.pop().ok_or(format!(\"unmatched ] at {}\", i))?;\n            jump.insert(open, i);\n            jump.insert(i, open);\n        }\n    }\n    if let Some(i) = stack.pop() { return Err(format!(\"unmatched [ at {}\", i)); }\n\n    let mut tape = vec![0u8; 30000];\n    let (mut ptr, mut pc, mut steps) = (0usize, 0usize, 0usize);\n    let mut out = String::new();\n    while pc < code.len() {\n        steps += 1;\n        if steps > max_steps { return Err(\"step limit exceeded\".to_string()); }\n        match code[pc] {\n            '+' => tape[ptr] = tape[ptr].wrapping_add(1),\n            '-' => tape[ptr] = tape[ptr].wrapping_sub(1),\n            '>' => ptr += 1,\n            '<' => ptr = ptr.checked_sub(1).ok_or(\"pointer moved left of the tape\")?,\n            '.' => out.push(tape[ptr] as char),\n            '[' => if tape[ptr] == 0 { pc = jump[&pc]; },\n            ']' => if tape[ptr] != 0 { pc = jump[&pc]; },\n            _ => {}\n        }\n        pc += 1;\n    }\n    println!(\"({} steps)\", steps);\n    Ok(out)\n}\n\nfn main() {\n    let hello = \"++++++++[>++++[>++>+++>+++>+<<<<-]>+>+>->>+[<]<-]>>.>---.+++++++..+++.>>.<-.<.+++.------.--------.>>+.\";\n    match run(hello, 1_000_000) {\n        Ok(s) => println!(\"output: {}\", s.trim_end()),\n        Err(e) => println!(\"error: {}\", e),\n    }\n    // countdown: prints 9876543210 using a loop and two cells\n    let countdown = \"++++++++++>+++++++[>++++++++<-]>+<<[>>.-<<-]\";\n    match run(countdown, 5_000) {\n        Ok(s) => println!(\"countdown: {}\", s),\n        Err(e) => println!(\"error: {}\", e),\n    }\n    println!(\"{:?}\", run(\"[[]\", 10));\n}\n", "Expression calculator": "// A recursive-descent expression calculator: tokenizer -> parser -> evaluator, with error messages.\nuse std::collections::HashMap;\n\n#[derive(Debug, Clone, PartialEq)]\nenum Tok { Num(f64), Ident(String), Op(char), LParen, RParen }\n\nfn tokenize(s: &str) -> Result<Vec<Tok>, String> {\n    let chars: Vec<char> = s.chars().collect();\n    let mut i = 0;\n    let mut out = Vec::new();\n    while i < chars.len() {\n        let c = chars[i];\n        if c.is_whitespace() { i += 1; }\n        else if c.is_ascii_digit() || c == '.' {\n            let st = i;\n            while i < chars.len() && (chars[i].is_ascii_digit() || chars[i] == '.') { i += 1; }\n            let t: String = chars[st..i].iter().collect();\n            out.push(Tok::Num(t.parse().map_err(|_| format!(\"bad number '{}'\", t))?));\n        } else if c.is_alphabetic() {\n            let st = i;\n            while i < chars.len() && chars[i].is_alphanumeric() { i += 1; }\n            out.push(Tok::Ident(chars[st..i].iter().collect()));\n        } else if \"+-*/^\".contains(c) { out.push(Tok::Op(c)); i += 1; }\n        else if c == '(' { out.push(Tok::LParen); i += 1; }\n        else if c == ')' { out.push(Tok::RParen); i += 1; }\n        else { return Err(format!(\"unexpected character '{}' at {}\", c, i)); }\n    }\n    Ok(out)\n}\n\nstruct Parser<'a> { toks: Vec<Tok>, pos: usize, vars: &'a HashMap<String, f64> }\n\nimpl<'a> Parser<'a> {\n    fn peek(&self) -> Option<&Tok> { self.toks.get(self.pos) }\n    fn next(&mut self) -> Option<Tok> { let t = self.toks.get(self.pos).cloned(); self.pos += 1; t }\n    // expr := term (('+'|'-') term)*\n    fn expr(&mut self) -> Result<f64, String> {\n        let mut v = self.term()?;\n        while let Some(Tok::Op(c)) = self.peek().cloned() {\n            if c != '+' && c != '-' { break; }\n            self.next();\n            let r = self.term()?;\n            v = if c == '+' { v + r } else { v - r };\n        }\n        Ok(v)\n    }\n    // term := power (('*'|'/') power)*\n    fn term(&mut self) -> Result<f64, String> {\n        let mut v = self.power()?;\n        while let Some(Tok::Op(c)) = self.peek().cloned() {\n            if c != '*' && c != '/' { break; }\n            self.next();\n            let r = self.power()?;\n            if c == '/' && r == 0.0 { return Err(\"division by zero\".to_string()); }\n            v = if c == '*' { v * r } else { v / r };\n        }\n        Ok(v)\n    }\n    // power := unary ('^' power)?   (right associative)\n    fn power(&mut self) -> Result<f64, String> {\n        let base = self.unary()?;\n        if let Some(Tok::Op('^')) = self.peek() { self.next(); let e = self.power()?; return Ok(base.powf(e)); }\n        Ok(base)\n    }\n    fn unary(&mut self) -> Result<f64, String> {\n        if let Some(Tok::Op('-')) = self.peek() { self.next(); return Ok(-self.unary()?); }\n        self.atom()\n    }\n    fn atom(&mut self) -> Result<f64, String> {\n        match self.next() {\n            Some(Tok::Num(n)) => Ok(n),\n            Some(Tok::Ident(name)) => {\n                if let Some(Tok::LParen) = self.peek() {\n                    self.next();\n                    let arg = self.expr()?;\n                    match self.next() { Some(Tok::RParen) => {}, _ => return Err(\"expected ')'\".to_string()) }\n                    match name.as_str() {\n                        \"sqrt\" => Ok(arg.sqrt()), \"sin\" => Ok(arg.sin()), \"cos\" => Ok(arg.cos()), \"abs\" => Ok(arg.abs()),\n                        \"ln\" => Ok(arg.ln()), _ => Err(format!(\"unknown function '{}'\", name)),\n                    }\n                } else {\n                    self.vars.get(&name).copied().ok_or(format!(\"unknown variable '{}'\", name))\n                }\n            }\n            Some(Tok::LParen) => {\n                let v = self.expr()?;\n                match self.next() { Some(Tok::RParen) => Ok(v), _ => Err(\"expected ')'\".to_string()) }\n            }\n            Some(t) => Err(format!(\"unexpected token {:?}\", t)),\n            None => Err(\"unexpected end of input\".to_string()),\n        }\n    }\n}\n\nfn eval(s: &str, vars: &HashMap<String, f64>) -> Result<f64, String> {\n    let toks = tokenize(s)?;\n    let mut p = Parser { toks, pos: 0, vars };\n    let v = p.expr()?;\n    if p.pos < p.toks.len() { return Err(format!(\"unexpected token {:?}\", p.toks[p.pos])); }\n    Ok(v)\n}\n\nfn main() {\n    let mut vars = HashMap::new();\n    vars.insert(\"pi\".to_string(), std::f64::consts::PI);\n    vars.insert(\"r\".to_string(), 2.5);\n    let tests = [\"1 + 2 * 3\", \"(1 + 2) * 3\", \"2 ^ 3 ^ 2\", \"-4 + 10 / 4\", \"pi * r ^ 2\", \"sqrt(144) + abs(-3)\",\n                 \"10 / (5 - 5)\", \"2 +\", \"3 $ 4\", \"foo(1)\", \"x * 2\"];\n    for t in tests.iter() {\n        match eval(t, &vars) {\n            Ok(v) => println!(\"{:<22} = {}\", t, v),\n            Err(e) => println!(\"{:<22} ! {}\", t, e),\n        }\n    }\n}\n", "Maze solver (BFS)": "// Shortest path through an ASCII maze with breadth-first search, then draw the route.\nuse std::collections::VecDeque;\n\nfn main() {\n    let maze = [\n        \"S.#.........#..\",\n        \".##.#######.#.#\",\n        \"....#.....#.#..\",\n        \".####.###.#.##.\",\n        \".#....#...#....\",\n        \".#.####.#####.#\",\n        \".#.#....#.....#\",\n        \".#.#.####.###..\",\n        \"...#......#...E\",\n    ];\n    let grid: Vec<Vec<char>> = maze.iter().map(|r| r.chars().collect()).collect();\n    let (h, w) = (grid.len(), grid[0].len());\n    let find = |t: char| -> (usize, usize) {\n        for y in 0..h { for x in 0..w { if grid[y][x] == t { return (y, x); } } }\n        panic!(\"missing {}\", t)\n    };\n    let (start, goal) = (find('S'), find('E'));\n\n    let mut prev: Vec<Vec<Option<(usize, usize)>>> = vec![vec![None; w]; h];\n    let mut seen = vec![vec![false; w]; h];\n    let mut q = VecDeque::new();\n    q.push_back(start);\n    seen[start.0][start.1] = true;\n    let mut visited = 0;\n    while let Some((y, x)) = q.pop_front() {\n        visited += 1;\n        if (y, x) == goal { break; }\n        let dirs: [(i32, i32); 4] = [(0, 1), (1, 0), (0, -1), (-1, 0)];\n        for (dy, dx) in dirs.iter() {\n            let (ny, nx) = (y as i32 + dy, x as i32 + dx);\n            if ny < 0 || nx < 0 || ny >= h as i32 || nx >= w as i32 { continue; }\n            let (ny, nx) = (ny as usize, nx as usize);\n            if grid[ny][nx] == '#' || seen[ny][nx] { continue; }\n            seen[ny][nx] = true;\n            prev[ny][nx] = Some((y, x));\n            q.push_back((ny, nx));\n        }\n    }\n\n    let mut out = grid.clone();\n    let mut cur = goal;\n    let mut len = 0;\n    while let Some(p) = prev[cur.0][cur.1] {\n        if p != start { out[p.0][p.1] = '*'; }\n        cur = p;\n        len += 1;\n    }\n    if len == 0 { println!(\"no path!\"); return; }\n    for row in &out { println!(\"{}\", row.iter().collect::<String>()); }\n    println!(\"\\nshortest path: {} steps (explored {} cells)\", len, visited);\n}\n"}, "groups": {"Emulation": ["NES: 6502 CPU emulator", "NES: tile / PPU renderer"], "Projects": ["Game of Life", "Tic-tac-toe AI", "Brainfuck interpreter", "Expression calculator", "Maze solver (BFS)"]}}, "java": {"examples": {"Hello, Java": "import java.util.*;\nimport java.util.stream.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(\"Hello from Java \" + System.getProperty(\"java.version\") + \"!\");\n\n        List<String> langs = Arrays.asList(\"Java\", \"Rust\", \"C\", \"Python\", \"TypeScript\");\n        System.out.println(\"sorted by length: \" +\n            langs.stream().sorted(Comparator.comparingInt(String::length).thenComparing(s -> s)).collect(Collectors.toList()));\n\n        Map<Integer, List<String>> byLen = langs.stream().collect(Collectors.groupingBy(String::length, TreeMap::new, Collectors.toList()));\n        byLen.forEach((len, names) -> System.out.println(len + \" letters: \" + names));\n\n        int sum = IntStream.rangeClosed(1, 100).filter(n -> n % 3 == 0 || n % 5 == 0).sum();\n        System.out.println(\"sum of multiples of 3 or 5 up to 100 = \" + sum);\n    }\n}\n", "Bank accounts (OOP)": "import java.util.*;\n\npublic class Main {\n    static class InsufficientFundsException extends Exception {\n        InsufficientFundsException(String msg) { super(msg); }\n    }\n\n    interface Account {\n        void deposit(double amount);\n        void withdraw(double amount) throws InsufficientFundsException;\n        double getBalance();\n    }\n\n    static abstract class BaseAccount implements Account {\n        protected double balance;\n        protected final String owner;\n        protected final List<String> history = new ArrayList<>();\n        BaseAccount(String owner, double opening) { this.owner = owner; this.balance = opening; }\n        public void deposit(double amount) { balance += amount; history.add(\"deposit \" + amount); }\n        public double getBalance() { return balance; }\n        abstract double monthlyInterest();\n    }\n\n    static class Savings extends BaseAccount {\n        Savings(String owner, double opening) { super(owner, opening); }\n        public void withdraw(double amount) throws InsufficientFundsException {\n            if (amount > balance) throw new InsufficientFundsException(owner + \": cannot withdraw \" + amount + \", balance \" + balance);\n            balance -= amount; history.add(\"withdraw \" + amount);\n        }\n        double monthlyInterest() { return balance * 0.02 / 12; }\n    }\n\n    static class Checking extends BaseAccount {\n        Checking(String owner, double opening) { super(owner, opening); }\n        public void withdraw(double amount) throws InsufficientFundsException {\n            if (amount > balance + 100) throw new InsufficientFundsException(owner + \": overdraft limit exceeded\");\n            balance -= amount; history.add(\"withdraw \" + amount);\n        }\n        double monthlyInterest() { return 0; }\n    }\n\n    public static void main(String[] args) {\n        List<BaseAccount> accounts = new ArrayList<>();\n        accounts.add(new Savings(\"Ada\", 500));\n        accounts.add(new Checking(\"Linus\", 50));\n        for (BaseAccount a : accounts) {\n            try {\n                a.deposit(25);\n                a.withdraw(160);\n                a.withdraw(500);\n            } catch (InsufficientFundsException e) {\n                System.out.println(\"error: \" + e.getMessage());\n            }\n            System.out.printf(\"%s (%s): balance=%.2f interest=%.2f history=%s%n\",\n                a.owner, a.getClass().getSimpleName(), a.getBalance(), a.monthlyInterest(), a.history);\n        }\n    }\n}\n", "Sorting algorithms": "import java.util.*;\n\npublic class Main {\n    static void bar(int[] a, int hi, int lo) {\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < a.length; i++) {\n            String cell = String.format(\"%2d\", a[i]);\n            sb.append((i == hi || i == lo) ? \"[\" + cell + \"]\" : \" \" + cell + \" \");\n        }\n        System.out.println(sb);\n    }\n\n    static void quickSort(int[] a, int lo, int hi, int[] steps) {\n        if (lo >= hi) return;\n        int pivot = a[hi], i = lo - 1;\n        for (int j = lo; j < hi; j++) {\n            if (a[j] < pivot) {\n                i++;\n                int t = a[i]; a[i] = a[j]; a[j] = t;\n                steps[0]++;\n                bar(a, i, j);\n            }\n        }\n        int t = a[i + 1]; a[i + 1] = a[hi]; a[hi] = t;\n        steps[0]++;\n        bar(a, i + 1, hi);\n        quickSort(a, lo, i, steps);\n        quickSort(a, i + 2, hi, steps);\n    }\n\n    public static void main(String[] args) {\n        int[] a = {9, 4, 7, 1, 8, 2, 6, 3, 5};\n        System.out.println(\"quicksort steps (brackets = elements just swapped):\");\n        bar(a, -1, -1);\n        int[] steps = {0};\n        quickSort(a, 0, a.length - 1, steps);\n        System.out.println(\"sorted: \" + Arrays.toString(a) + \" in \" + steps[0] + \" swaps\");\n    }\n}\n", "Threads & executors": "import java.util.*;\nimport java.util.concurrent.*;\nimport java.util.concurrent.atomic.AtomicInteger;\n\npublic class Main {\n    static long fib(int n) { return n < 2 ? n : fib(n - 1) + fib(n - 2); }\n\n    public static void main(String[] args) throws Exception {\n        ExecutorService pool = Executors.newFixedThreadPool(4);\n        List<Future<String>> futures = new ArrayList<>();\n        for (int n : new int[]{20, 25, 30, 32}) {\n            futures.add(pool.submit(() -> \"fib(\" + n + \") = \" + fib(n)));\n        }\n        for (Future<String> f : futures) System.out.println(f.get());\n\n        // many threads incrementing a shared counter safely\n        AtomicInteger counter = new AtomicInteger();\n        CountDownLatch done = new CountDownLatch(8);\n        for (int t = 0; t < 8; t++) {\n            pool.execute(() -> {\n                for (int i = 0; i < 10_000; i++) counter.incrementAndGet();\n                done.countDown();\n            });\n        }\n        done.await();\n        System.out.println(\"counter = \" + counter.get() + \" (expected 80000)\");\n        pool.shutdown();\n        System.out.println(\"pool terminated: \" + pool.awaitTermination(2, TimeUnit.SECONDS));\n    }\n}\n", "LRU cache": "import java.util.*;\n\npublic class Main {\n    // LRU cache built on LinkedHashMap's access-order mode\n    static class LRU<K, V> extends LinkedHashMap<K, V> {\n        private final int capacity;\n        LRU(int capacity) { super(16, 0.75f, true); this.capacity = capacity; }\n        @Override protected boolean removeEldestEntry(Map.Entry<K, V> eldest) { return size() > capacity; }\n    }\n\n    public static void main(String[] args) {\n        LRU<String, Integer> cache = new LRU<>(3);\n        cache.put(\"a\", 1);\n        cache.put(\"b\", 2);\n        cache.put(\"c\", 3);\n        System.out.println(\"start:        \" + cache.keySet());\n        cache.get(\"a\");\n        System.out.println(\"read a:       \" + cache.keySet());\n        cache.put(\"d\", 4);\n        System.out.println(\"put d (evict b): \" + cache.keySet());\n        cache.put(\"e\", 5);\n        System.out.println(\"put e (evict c): \" + cache.keySet());\n        System.out.println(\"contains b? \" + cache.containsKey(\"b\"));\n    }\n}\n"}, "groups": {"Basics": ["Hello, Java"], "Projects": ["Bank accounts (OOP)", "Sorting algorithms", "Threads & executors", "LRU cache"]}}, "csharp": {"examples": {"Hello, C#": "using System;\nusing System.Collections.Generic;\nusing System.Linq;\n\nclass Program\n{\n    static void Main()\n    {\n        Console.WriteLine(\"Hello from C# on \" + Environment.Version + \"!\");\n\n        var langs = new List<string> { \"C#\", \"Rust\", \"C\", \"Python\", \"TypeScript\" };\n        Console.WriteLine(\"sorted by length: \" + string.Join(\", \", langs.OrderBy(s => s.Length).ThenBy(s => s)));\n\n        foreach (var g in langs.GroupBy(s => s.Length).OrderBy(g => g.Key))\n            Console.WriteLine($\"{g.Key} letters: {string.Join(\", \", g)}\");\n\n        int sum = Enumerable.Range(1, 100).Where(n => n % 3 == 0 || n % 5 == 0).Sum();\n        Console.WriteLine($\"sum of multiples of 3 or 5 up to 100 = {sum}\");\n\n        (int min, int max) = (langs.Min(s => s.Length), langs.Max(s => s.Length));\n        Console.WriteLine($\"shortest name: {min} chars, longest: {max} chars\");\n    }\n}\n", "LINQ playground": "using System;\nusing System.Collections.Generic;\nusing System.Linq;\n\nclass Program\n{\n    class Employee { public string Name; public string Dept; public int Salary; public int Age; }\n\n    static void Main()\n    {\n        var staff = new List<Employee>\n        {\n            new Employee { Name = \"Ana\",   Dept = \"Eng\",   Salary = 120, Age = 31 },\n            new Employee { Name = \"Bo\",    Dept = \"Eng\",   Salary = 105, Age = 27 },\n            new Employee { Name = \"Cy\",    Dept = \"Ops\",   Salary = 80,  Age = 45 },\n            new Employee { Name = \"Di\",    Dept = \"Ops\",   Salary = 85,  Age = 38 },\n            new Employee { Name = \"Ed\",    Dept = \"Sales\", Salary = 70,  Age = 29 },\n        };\n\n        Console.WriteLine(\"-- average salary per department\");\n        foreach (var g in staff.GroupBy(e => e.Dept).Select(g => new { Dept = g.Key, Avg = g.Average(e => e.Salary), N = g.Count() }))\n            Console.WriteLine($\"{g.Dept,-6} avg={g.Avg,6:F1} n={g.N}\");\n\n        Console.WriteLine(\"-- top earner per department\");\n        foreach (var e in staff.GroupBy(x => x.Dept).Select(g => g.OrderByDescending(x => x.Salary).First()))\n            Console.WriteLine($\"{e.Dept,-6} {e.Name} ({e.Salary})\");\n\n        Console.WriteLine(\"-- join with budgets\");\n        var budgets = new Dictionary<string, int> { [\"Eng\"] = 300, [\"Ops\"] = 150, [\"Sales\"] = 90 };\n        var joined = from e in staff\n                     join b in budgets on e.Dept equals b.Key\n                     group e by new { e.Dept, b.Value } into g\n                     select new { g.Key.Dept, Used = g.Sum(x => x.Salary), Budget = g.Key.Value };\n        foreach (var r in joined) Console.WriteLine($\"{r.Dept,-6} {r.Used}/{r.Budget} {(r.Used > r.Budget ? \"OVER\" : \"ok\")}\");\n\n        Console.WriteLine(\"-- running total (Aggregate)\");\n        int running = 0;\n        Console.WriteLine(string.Join(\" \", staff.Select(e => running += e.Salary)));\n\n        Console.WriteLine(\"-- pagination: page 2, size 2\");\n        Console.WriteLine(string.Join(\", \", staff.OrderBy(e => e.Name).Skip(2).Take(2).Select(e => e.Name)));\n    }\n}\n", "Bank accounts (OOP)": "using System;\nusing System.Collections.Generic;\n\nclass InsufficientFunds : Exception\n{\n    public InsufficientFunds(decimal need, decimal have) : base($\"need {need:C}, have {have:C}\") { }\n}\n\nabstract class Account\n{\n    public string Owner { get; }\n    public decimal Balance { get; protected set; }\n    protected readonly List<string> History = new List<string>();\n\n    protected Account(string owner, decimal opening) { Owner = owner; Balance = opening; }\n\n    public void Deposit(decimal amount)\n    {\n        if (amount <= 0) throw new ArgumentException(\"deposit must be positive\");\n        Balance += amount; History.Add($\"+{amount}\");\n    }\n\n    public virtual void Withdraw(decimal amount)\n    {\n        if (amount > Balance) throw new InsufficientFunds(amount, Balance);\n        Balance -= amount; History.Add($\"-{amount}\");\n    }\n\n    public abstract string Kind { get; }\n    public override string ToString() => $\"{Kind,-8} {Owner,-6} {Balance,10:F2}  [{string.Join(\" \", History)}]\";\n}\n\nclass Checking : Account\n{\n    readonly decimal overdraft;\n    public Checking(string o, decimal open, decimal overdraft) : base(o, open) { this.overdraft = overdraft; }\n    public override string Kind => \"Checking\";\n    public override void Withdraw(decimal amount)\n    {\n        if (amount > Balance + overdraft) throw new InsufficientFunds(amount, Balance + overdraft);\n        Balance -= amount; History.Add($\"-{amount}\");\n    }\n}\n\nclass Savings : Account\n{\n    public Savings(string o, decimal open) : base(o, open) { }\n    public override string Kind => \"Savings\";\n    public void AddInterest(decimal rate) => Deposit(Math.Round(Balance * rate, 2));\n}\n\nclass Program\n{\n    static void Main()\n    {\n        var accounts = new List<Account> { new Checking(\"Ada\", 100, 50), new Savings(\"Linus\", 1000) };\n        accounts[0].Withdraw(120);                 // uses the overdraft\n        ((Savings)accounts[1]).AddInterest(0.02m);\n        foreach (var a in accounts) Console.WriteLine(a);\n\n        try { accounts[1].Withdraw(5000); }\n        catch (InsufficientFunds e) { Console.WriteLine(\"declined: \" + e.Message); }\n    }\n}\n", "Tasks, async & parallel": "using System;\nusing System.Collections.Generic;\nusing System.Linq;\nusing System.Threading;\nusing System.Threading.Tasks;\n\nclass Program\n{\n    static async Task<int> SquareAfterAsync(int n, int ms)\n    {\n        await Task.Delay(ms);\n        Console.WriteLine($\"  finished {n} on a pool thread: {Thread.CurrentThread.IsThreadPoolThread}\");\n        return n * n;\n    }\n\n    static async Task RunAsync()\n    {\n        Console.WriteLine(\"sequential:\");\n        var a = await SquareAfterAsync(2, 50);\n        var b = await SquareAfterAsync(3, 50);\n        Console.WriteLine($\"  {a} + {b} = {a + b}\");\n\n        Console.WriteLine(\"parallel with Task.WhenAll:\");\n        var results = await Task.WhenAll(Enumerable.Range(1, 5).Select(i => SquareAfterAsync(i, 120 - i * 20)));\n        Console.WriteLine(\"  results (input order): \" + string.Join(\", \", results));\n\n        Console.WriteLine(\"lock + Parallel.For:\");\n        long total = 0; var gate = new object();\n        Parallel.For(1, 1001, i => { lock (gate) total += i; });\n        Console.WriteLine(\"  sum 1..1000 = \" + total);\n\n        Console.WriteLine(\"cancellation:\");\n        var cts = new CancellationTokenSource(80);\n        try { await Task.Delay(1000, cts.Token); }\n        catch (OperationCanceledException) { Console.WriteLine(\"  cancelled after ~80 ms\"); }\n    }\n\n    static void Main()\n    {\n        RunAsync().GetAwaiter().GetResult();   // classic Main: works on every C# version\n    }\n}\n"}, "groups": {"Basics": ["Hello, C#", "LINQ playground"], "Projects": ["Bank accounts (OOP)", "Tasks, async & parallel"]}}, "c": {"examples": {"Hello, C": "#include <stdio.h>\n\nint main() {\n    printf(\"Hello from C!\\n\");\n    int n = 5;\n    int fact = 1;\n    for (int i = 2; i <= n; i++) fact *= i;\n    printf(\"%d! = %d\\n\", n, fact);\n    printf(\"size of int = %d bytes\\n\", (int)sizeof(int));\n    return 0;\n}\n", "Primes & arrays": "#include <stdio.h>\n\n#define LIMIT 60\n\nint main() {\n    int is_prime[LIMIT + 1];\n    int i, j;\n    for (i = 0; i <= LIMIT; i++) is_prime[i] = 1;\n    is_prime[0] = is_prime[1] = 0;\n    for (i = 2; i * i <= LIMIT; i++)\n        if (is_prime[i])\n            for (j = i * i; j <= LIMIT; j += i) is_prime[j] = 0;\n\n    printf(\"primes up to %d:\\n\", LIMIT);\n    int count = 0;\n    for (i = 2; i <= LIMIT; i++) {\n        if (is_prime[i]) {\n            printf(\"%3d\", i);\n            count++;\n            if (count % 10 == 0) printf(\"\\n\");\n        }\n    }\n    printf(\"\\n(%d primes)\\n\", count);\n\n    /* pointer walk over an array */\n    int data[5] = {10, 20, 30, 40, 50};\n    int *p = data;\n    int sum = 0;\n    for (i = 0; i < 5; i++) {\n        sum += *(p + i);\n    }\n    printf(\"sum via pointer = %d\\n\", sum);\n    return 0;\n}\n", "Matrix & strings": "#include <stdio.h>\n#include <string.h>\n#include <ctype.h>\n\nvoid multiply(int a[2][3], int b[3][2], int out[2][2]) {\n    for (int i = 0; i < 2; i++)\n        for (int j = 0; j < 2; j++) {\n            out[i][j] = 0;\n            for (int k = 0; k < 3; k++) out[i][j] += a[i][k] * b[k][j];\n        }\n}\n\nint is_palindrome(const char *s) {\n    int i = 0, j = (int)strlen(s) - 1;\n    while (i < j) {\n        while (i < j && !isalnum((unsigned char)s[i])) i++;\n        while (i < j && !isalnum((unsigned char)s[j])) j--;\n        if (tolower((unsigned char)s[i]) != tolower((unsigned char)s[j])) return 0;\n        i++; j--;\n    }\n    return 1;\n}\n\nvoid check(const char *s) {\n    printf(\"\\\"%s\\\" -> %s\\n\", s, is_palindrome(s) ? \"palindrome\" : \"not a palindrome\");\n}\n\nint main() {\n    int a[2][3] = {{1, 2, 3}, {4, 5, 6}};\n    int b[3][2] = {{7, 8}, {9, 10}, {11, 12}};\n    int c[2][2];\n    multiply(a, b, c);\n    printf(\"A x B =\\n\");\n    for (int i = 0; i < 2; i++) printf(\"[%4d %4d]\\n\", c[i][0], c[i][1]);\n\n    check(\"A man, a plan, a canal: Panama\");\n    check(\"Hello, World\");\n    check(\"Was it a car or a cat I saw?\");\n\n    const char *src = \"devportal\";\n    char word[20];\n    int n = 0;\n    while (src[n] != 0) { word[n] = toupper(src[n]); n++; }\n    word[n] = 0;\n    printf(\"%s has %d letters\\n\", word, n);\n    return 0;\n}\n", "Sorting race": "#include <stdio.h>\n\n#define N 12\n\nvoid print_arr(const char *label, int a[], int n) {\n    printf(\"%-10s\", label);\n    for (int i = 0; i < n; i++) printf(\"%3d\", a[i]);\n    printf(\"\\n\");\n}\n\nint bubble_sort(int a[], int n) {\n    int swaps = 0;\n    for (int i = 0; i < n - 1; i++)\n        for (int j = 0; j < n - 1 - i; j++)\n            if (a[j] > a[j + 1]) {\n                int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t;\n                swaps++;\n            }\n    return swaps;\n}\n\nint insertion_sort(int a[], int n) {\n    int moves = 0;\n    for (int i = 1; i < n; i++) {\n        int key = a[i];\n        int j = i - 1;\n        while (j >= 0 && a[j] > key) {\n            a[j + 1] = a[j];\n            j--;\n            moves++;\n        }\n        a[j + 1] = key;\n    }\n    return moves;\n}\n\nint main() {\n    int a[N] = {42, 7, 19, 3, 88, 23, 61, 5, 34, 12, 70, 1};\n    int b[N] = {42, 7, 19, 3, 88, 23, 61, 5, 34, 12, 70, 1};\n    print_arr(\"input:\", a, N);\n    int s1 = bubble_sort(a, N);\n    int s2 = insertion_sort(b, N);\n    print_arr(\"bubble:\", a, N);\n    print_arr(\"insertion:\", b, N);\n    printf(\"bubble swaps = %d, insertion shifts = %d\\n\", s1, s2);\n    return 0;\n}\n"}, "groups": {"Basics": ["Hello, C", "Primes & arrays", "Matrix & strings"], "Projects": ["Sorting race"]}}, "cpp": {"examples": {"Hello, C++": "#include <iostream>\nusing namespace std;\n\nint main() {\n    cout << \"Hello from C++!\" << endl;\n    int total = 0;\n    for (int i = 1; i <= 10; i++) {\n        total += i * i;\n    }\n    cout << \"sum of squares 1..10 = \" << total << endl;\n    double r = 2.5;\n    cout << \"circle area (r=2.5) = \" << 3.14159265 * r * r << endl;\n    return 0;\n}\n", "Overloads & shapes": "// C++ (subset simulator): functions, references-free math, loops.\n#include <iostream>\n#include <iomanip>\n#include <cmath>\nusing namespace std;\n\ndouble circleArea(double r) { return 3.14159265358979 * r * r; }\ndouble rectArea(double w, double h) { return w * h; }\ndouble triArea(double a, double b, double c) {\n    double s = (a + b + c) / 2;\n    return sqrt(s * (s - a) * (s - b) * (s - c));\n}\n\nint main() {\n    cout << fixed << setprecision(3);\n    cout << \"circle r=2.5   : \" << circleArea(2.5) << endl;\n    cout << \"rect 3x4.5     : \" << rectArea(3, 4.5) << endl;\n    cout << \"triangle 3-4-5 : \" << triArea(3, 4, 5) << endl;\n\n    cout << endl << \"Multiplication table\" << endl;\n    for (int i = 1; i <= 5; i++) {\n        for (int j = 1; j <= 5; j++) cout << setw(4) << i * j;\n        cout << endl;\n    }\n\n    cout << endl << \"Fibonacci:\";\n    int a = 0, b = 1;\n    for (int i = 0; i < 12; i++) {\n        cout << \" \" << a;\n        int t = a + b; a = b; b = t;\n    }\n    cout << endl;\n    return 0;\n}\n", "Bank account": "// C++ (subset simulator): a tiny bank using arrays and functions.\n#include <iostream>\n#include <iomanip>\nusing namespace std;\n\nint ids[3] = {101, 102, 103};\ndouble balance[3] = {250.0, 90.5, 1200.0};\n\nint find(int id) {\n    for (int i = 0; i < 3; i++) if (ids[i] == id) return i;\n    return -1;\n}\n\nint withdraw(int id, double amount) {\n    int i = find(id);\n    if (i < 0) { cout << \"  no such account \" << id << endl; return 0; }\n    if (amount > balance[i]) { cout << \"  insufficient funds in \" << id << endl; return 0; }\n    balance[i] = balance[i] - amount;\n    return 1;\n}\n\nint transfer(int from, int to, double amount) {\n    int j = find(to);\n    if (j < 0) { cout << \"  unknown target \" << to << endl; return 0; }\n    if (!withdraw(from, amount)) return 0;\n    balance[j] = balance[j] + amount;\n    return 1;\n}\n\nvoid report() {\n    cout << fixed << setprecision(2);\n    for (int i = 0; i < 3; i++)\n        cout << \"  #\" << ids[i] << \"  $\" << setw(8) << balance[i] << endl;\n}\n\nint main() {\n    cout << \"Opening balances\" << endl;\n    report();\n    cout << \"transfer 101 -> 102 : 75.25\" << endl;\n    transfer(101, 102, 75.25);\n    cout << \"transfer 102 -> 103 : 500\" << endl;\n    transfer(102, 103, 500);\n    cout << \"transfer 103 -> 999 : 10\" << endl;\n    transfer(103, 999, 10);\n    cout << \"Final balances\" << endl;\n    report();\n    return 0;\n}\n", "Tic-tac-toe bots": "// C++ (subset simulator): tic-tac-toe, two simple bots play each other.\n#include <iostream>\nusing namespace std;\n\nchar board[9];\n\nvoid show() {\n    for (int r = 0; r < 3; r++) {\n        cout << \" \" << board[r*3] << \" | \" << board[r*3+1] << \" | \" << board[r*3+2] << endl;\n        if (r < 2) cout << \"---+---+---\" << endl;\n    }\n    cout << endl;\n}\n\nint winner() {\n    int w[8][3] = {{0,1,2},{3,4,5},{6,7,8},{0,3,6},{1,4,7},{2,5,8},{0,4,8},{2,4,6}};\n    for (int i = 0; i < 8; i++)\n        if (board[w[i][0]] != ' ' && board[w[i][0]] == board[w[i][1]] && board[w[i][1]] == board[w[i][2]]) return 1;\n    return 0;\n}\n\n// first try to win, then block, then centre, corners, edges\nint pick(char me, char other) {\n    int w[8][3] = {{0,1,2},{3,4,5},{6,7,8},{0,3,6},{1,4,7},{2,5,8},{0,4,8},{2,4,6}};\n    for (int pass = 0; pass < 2; pass++) {\n        char who = pass == 0 ? me : other;\n        for (int i = 0; i < 8; i++) {\n            int cnt = 0, empty = -1;\n            for (int k = 0; k < 3; k++) {\n                int c = w[i][k];\n                if (board[c] == who) cnt++;\n                else if (board[c] == ' ') empty = c;\n            }\n            if (cnt == 2 && empty >= 0) return empty;\n        }\n    }\n    int order[9] = {4, 0, 2, 6, 8, 1, 3, 5, 7};\n    for (int i = 0; i < 9; i++) if (board[order[i]] == ' ') return order[i];\n    return -1;\n}\n\nint main() {\n    for (int i = 0; i < 9; i++) board[i] = ' ';\n    char turn = 'X';\n    for (int move = 0; move < 9; move++) {\n        char other = turn == 'X' ? 'O' : 'X';\n        int c = pick(turn, other);\n        board[c] = turn;\n        cout << \"Move \" << move + 1 << \": \" << turn << \" plays square \" << c + 1 << endl;\n        if (winner()) { show(); cout << turn << \" wins!\" << endl; return 0; }\n        turn = other;\n    }\n    show();\n    cout << \"It's a draw.\" << endl;\n    return 0;\n}\n"}, "groups": {"Basics": ["Hello, C++", "Overloads & shapes"], "Projects": ["Bank account", "Tic-tac-toe bots"]}}, "ansible": {"examples": {"Ping & facts": "---\n# The simplest possible playbook: can we reach every host, and what do we know about them?\n- name: Check connectivity and gather facts\n  hosts: all\n  tasks:\n    - name: Ping\n      ansible.builtin.ping:\n\n    - name: Who are we?\n      ansible.builtin.command: whoami\n      register: me\n      changed_when: false\n\n    - name: Print a fact report\n      ansible.builtin.debug:\n        msg:\n          - \"host      : {{ inventory_hostname }} ({{ ansible_host }})\"\n          - \"os        : {{ ansible_distribution }} {{ ansible_distribution_version }} / {{ ansible_kernel }}\"\n          - \"cpus / ram: {{ ansible_processor_vcpus }} / {{ ansible_memtotal_mb }} MB\"\n          - \"ssh user  : {{ me.stdout }}\"\n          - \"groups    : {{ group_names | join(', ') }}\"\n", "Web server (nginx)": "---\n# Configure the web servers: install nginx, deploy a page, start the service.\n# Run it twice — the second run reports \"ok\" instead of \"changed\" (idempotency!).\n- name: Configure web servers\n  hosts: webservers\n  become: true\n  vars:\n    site_title: \"DevPortal demo\"\n    packages:\n      - nginx\n      - curl\n  tasks:\n    - name: Install packages\n      ansible.builtin.apt:\n        name: \"{{ packages }}\"\n        state: present\n        update_cache: true\n\n    - name: Deploy the landing page\n      ansible.builtin.copy:\n        dest: /var/www/html/index.html\n        content: |\n          <h1>{{ site_title }}<\/h1>\n          <p>Served by {{ inventory_hostname }} ({{ ansible_default_ipv4.address }})<\/p>\n        mode: \"0644\"\n      notify: Reload nginx\n\n    - name: Make sure nginx is running and enabled\n      ansible.builtin.service:\n        name: nginx\n        state: started\n        enabled: true\n\n    - name: Wait for port 80\n      ansible.builtin.wait_for:\n        port: 80\n        timeout: 10\n\n    - name: Show where it runs\n      ansible.builtin.debug:\n        msg: \"{{ inventory_hostname }} is serving on port {{ http_port }}\"\n\n  handlers:\n    - name: Reload nginx\n      ansible.builtin.service:\n        name: nginx\n        state: reloaded\n", "Variables, loops & when": "---\n# Variables, loops, conditionals, register — the core Ansible toolkit.\n- name: Loops and conditionals\n  hosts: all\n  become: true\n  vars:\n    team:\n      - { name: alice, groups: \"sudo\",   shell: /bin/bash }\n      - { name: bob,   groups: \"deploy\", shell: /bin/bash }\n      - { name: carol, groups: \"deploy\", shell: /usr/sbin/nologin }\n    env: staging\n  tasks:\n    - name: Show some gathered facts\n      ansible.builtin.debug:\n        msg: \"{{ inventory_hostname }}: {{ ansible_distribution }} {{ ansible_distribution_version }}, {{ ansible_processor_vcpus }} vCPUs, {{ ansible_memtotal_mb }} MB RAM\"\n\n    - name: Create the team accounts (a loop over a list of dicts)\n      ansible.builtin.user:\n        name: \"{{ item.name }}\"\n        groups: \"{{ item.groups }}\"\n        shell: \"{{ item.shell }}\"\n        append: true\n      loop: \"{{ team }}\"\n      loop_control:\n        label: \"{{ item.name }}\"\n\n    - name: Only on web servers — install nginx\n      ansible.builtin.apt:\n        name: nginx\n        state: present\n      when: \"'webservers' in group_names\"\n\n    - name: Only on database servers — install PostgreSQL\n      ansible.builtin.apt:\n        name: postgresql\n        state: present\n      when: \"'dbservers' in group_names\"\n\n    - name: Check what is listening on the web port\n      ansible.builtin.command: systemctl is-active nginx\n      register: nginx_state\n      changed_when: false\n      failed_when: false\n\n    - name: Report nginx state\n      ansible.builtin.debug:\n        msg: \"nginx is {{ nginx_state.stdout | default('unknown') }} on {{ inventory_hostname }}\"\n\n    - name: Drop a marker file only when env is production\n      ansible.builtin.file:\n        path: /etc/PRODUCTION\n        state: touch\n      when: env == \"production\"\n\n    - name: Count how many users we manage\n      ansible.builtin.set_fact:\n        managed: \"{{ team | map(attribute='name') | list }}\"\n\n    - name: Summary\n      ansible.builtin.debug:\n        msg: \"Managed users ({{ managed | length }}): {{ managed | join(', ') }}\"\n", "Errors: block / rescue": "---\n# Error handling: ignore_errors, failed_when, assert, and block / rescue / always.\n- name: When things go wrong\n  hosts: webservers\n  become: true\n  tasks:\n    - name: A command that fails, but we do not care\n      ansible.builtin.command: \"false\"\n      ignore_errors: true\n\n    - name: Fail only when the output says so (failed_when)\n      ansible.builtin.command: echo \"disk usage 91%\"\n      register: disk\n      failed_when: \"'9' in disk.stdout\"\n      ignore_errors: true\n\n    - name: Assert something about the host\n      ansible.builtin.assert:\n        that:\n          - ansible_processor_vcpus >= 2\n          - inventory_hostname.startswith(\"web\")\n        success_msg: \"Host looks good\"\n\n    - name: Try something risky, recover, always clean up\n      block:\n        - name: Install a package that does not exist\n          ansible.builtin.apt:\n            name: this-package-does-not-exist\n            state: present\n\n        - name: This is skipped because the block already failed\n          ansible.builtin.debug:\n            msg: \"you should never see me\"\n      rescue:\n        - name: Recover — install a package that does\n          ansible.builtin.apt:\n            name: htop\n            state: present\n\n        - name: Tell everyone what happened\n          ansible.builtin.debug:\n            msg: \"Rescued on {{ inventory_hostname }}\"\n      always:\n        - name: Always write an audit line\n          ansible.builtin.lineinfile:\n            path: /var/log/deploy.log\n            line: \"deploy attempt finished on {{ inventory_hostname }}\"\n            create: true\n\n    - name: And now one real failure (stops this host)\n      ansible.builtin.fail:\n        msg: \"Deliberate failure — check the PLAY RECAP below\"\n\n    - name: Never reached\n      ansible.builtin.debug:\n        msg: \"unreachable code\"\n", "Mistake: forgot become": "---\n# A classic beginner mistake: system changes need root, and this play never asks for it.\n# Read the errors, then add `become: true` under `hosts:` and run it again.\n- name: Install and configure nginx\n  hosts: webservers\n  # become: true        # <-- uncomment me!\n  tasks:\n    - name: Install nginx\n      ansible.builtin.apt:\n        name: nginx\n        state: present\n\n    - name: Write a config snippet\n      ansible.builtin.copy:\n        dest: /etc/nginx/conf.d/devportal.conf\n        content: \"server_tokens off;\\n\"\n\n    - name: A file in our own home directory works without root\n      ansible.builtin.copy:\n        dest: /home/deploy/notes.txt\n        content: \"no sudo needed here\\n\"\n", "Harden: users, ssh, firewall": "---\n# Server hardening: users, SSH configuration, firewall and a scheduled job.\n- name: Harden servers\n  hosts: all\n  become: true\n  vars:\n    ssh_port: 22\n    admins: [alice, bob]\n  tasks:\n    - name: Create the admin group\n      ansible.builtin.group:\n        name: admins\n        state: present\n\n    - name: Create admin users\n      ansible.builtin.user:\n        name: \"{{ item }}\"\n        groups: admins,sudo\n        append: true\n        shell: /bin/bash\n      loop: \"{{ admins }}\"\n\n    - name: Install firewall and fail2ban\n      ansible.builtin.apt:\n        name: [ufw, fail2ban]\n        state: present\n        update_cache: true\n\n    - name: Harden sshd_config\n      ansible.builtin.lineinfile:\n        path: /etc/ssh/sshd_config\n        regexp: \"^#?{{ item.key }}\"\n        line: \"{{ item.key }} {{ item.value }}\"\n        create: true\n      loop:\n        - { key: PermitRootLogin, value: \"no\" }\n        - { key: PasswordAuthentication, value: \"no\" }\n        - { key: Port, value: \"{{ ssh_port }}\" }\n      notify: Restart ssh\n\n    - name: Allow SSH and HTTP through the firewall\n      community.general.ufw:\n        rule: allow\n        port: \"{{ item }}\"\n        proto: tcp\n      loop: [22, 80]\n\n    - name: Enable the firewall\n      community.general.ufw:\n        state: enabled\n\n    - name: Nightly log cleanup at 02:30\n      ansible.builtin.cron:\n        name: log cleanup\n        minute: \"30\"\n        hour: \"2\"\n        job: \"find /var/log -name '*.gz' -mtime +14 -delete\"\n\n  handlers:\n    - name: Restart ssh\n      ansible.builtin.service:\n        name: ssh\n        state: restarted\n", "Database server": "---\n# PostgreSQL server with a nightly backup cron job — then a little verification.\n- name: Set up the database tier\n  hosts: dbservers\n  become: true\n  vars:\n    db_name: devportal\n    backup_dir: /var/backups/postgres\n  tasks:\n    - name: Install PostgreSQL\n      ansible.builtin.apt:\n        name: postgresql\n        state: present\n        update_cache: true\n\n    - name: Ensure PostgreSQL is running at boot\n      ansible.builtin.systemd:\n        name: postgresql\n        state: started\n        enabled: true\n\n    - name: Create the backup directory\n      ansible.builtin.file:\n        path: \"{{ backup_dir }}\"\n        state: directory\n        mode: \"0750\"\n        owner: root\n\n    - name: Tune a setting\n      ansible.builtin.lineinfile:\n        path: /etc/postgresql/15/main/postgresql.conf\n        regexp: \"^#?max_connections\"\n        line: \"max_connections = 200\"\n      notify: Restart PostgreSQL\n\n    - name: Schedule the nightly backup\n      ansible.builtin.cron:\n        name: \"backup {{ db_name }}\"\n        minute: \"15\"\n        hour: \"3\"\n        job: \"pg_dump {{ db_name }} > {{ backup_dir }}/{{ db_name }}.sql\"\n\n    - name: Wait until PostgreSQL accepts connections\n      ansible.builtin.wait_for:\n        port: 5432\n        timeout: 30\n\n    - name: Verify the server\n      ansible.builtin.stat:\n        path: /etc/postgresql/15/main/postgresql.conf\n      register: conf\n\n    - name: Report\n      ansible.builtin.debug:\n        msg: \"config exists: {{ conf.stat.exists }}, {{ conf.stat.size }} bytes\"\n\n  handlers:\n    - name: Restart PostgreSQL\n      ansible.builtin.service:\n        name: postgresql\n        state: restarted\n", "Unreachable host (own inventory)": "---\n# One host in the inventory is offline. Ansible reports UNREACHABLE for it and carries on with the rest.\n# (This example loads its own inventory, with an extra host called \"legacy-down\".)\n- name: Patch everything we can reach\n  hosts: all\n  become: true\n  tasks:\n    - name: Ping\n      ansible.builtin.ping:\n\n    - name: Install security tooling\n      ansible.builtin.apt:\n        name: fail2ban\n        state: present\n"}, "groups": {"Start here": ["Ping & facts", "Web server (nginx)"], "Core concepts": ["Variables, loops & when", "Errors: block / rescue", "Mistake: forgot become"], "Real-world": ["Harden: users, ssh, firewall", "Database server", "Unreachable host (own inventory)"]}, "inventories": {"Unreachable host (own inventory)": "[webservers]\nweb1 ansible_host=10.0.1.11\nweb2 ansible_host=10.0.1.12\n\n[legacy]\nlegacy-down ansible_host=unreachable\n\n[all:vars]\nansible_user=deploy\n"}}, "sql": {"examples": {"SQLite: hello, temp table": "-- dialect: sqlite\n-- A real SQLite database running in your browser. Every run starts empty, so scripts are repeatable.\nCREATE TEMP TABLE planets (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  moons INTEGER,\n  diameter_km INTEGER\n);\n\nINSERT INTO planets (name, moons, diameter_km) VALUES\n  ('Mercury', 0, 4879),\n  ('Venus',   0, 12104),\n  ('Earth',   1, 12756),\n  ('Mars',    2, 6792),\n  ('Jupiter', 95, 142984),\n  ('Saturn',  146, 120536);\n\n-- the whole table\nSELECT * FROM planets;\n\n-- filter, compute, sort\nSELECT name, moons, ROUND(diameter_km / 12756.0, 2) AS earths_wide\nFROM planets\nWHERE moons > 0\nORDER BY diameter_km DESC;\n\n-- aggregate\nSELECT COUNT(*) AS planets, SUM(moons) AS total_moons, MAX(diameter_km) AS widest FROM planets;\n", "SQLite: joins with temp tables": "-- dialect: sqlite\n-- Temp tables live only for this session, so they are perfect for practice: nothing to clean up.\nCREATE TEMP TABLE customers (id INTEGER PRIMARY KEY, name TEXT, city TEXT);\nCREATE TEMP TABLE orders    (id INTEGER PRIMARY KEY, customer_id INTEGER, amount REAL, placed DATE);\n\nINSERT INTO customers VALUES (1,'Ada','London'), (2,'Linus','Helsinki'), (3,'Grace','New York'), (4,'Alan','London');\nINSERT INTO orders VALUES\n  (1, 1, 120.50, '2024-01-05'), (2, 1,  80.00, '2024-02-11'), (3, 2, 45.25, '2024-02-14'),\n  (4, 3, 300.00, '2024-03-02'), (5, 1,  19.99, '2024-03-09');\n\n-- INNER JOIN: customers who ordered\nSELECT c.name, COUNT(o.id) AS orders, ROUND(SUM(o.amount), 2) AS spent\nFROM customers c JOIN orders o ON o.customer_id = c.id\nGROUP BY c.id ORDER BY spent DESC;\n\n-- LEFT JOIN: everyone, including customers with no orders\nSELECT c.name, IFNULL(SUM(o.amount), 0) AS spent\nFROM customers c LEFT JOIN orders o ON o.customer_id = c.id\nGROUP BY c.id ORDER BY c.name;\n\n-- Materialise a result into a second temp table, then query that\nCREATE TEMP TABLE big_spenders AS\n  SELECT customer_id, SUM(amount) AS spent FROM orders GROUP BY customer_id HAVING SUM(amount) > 100;\nSELECT c.name, b.spent FROM big_spenders b JOIN customers c ON c.id = b.customer_id;\n", "PostgreSQL: hello, temp table": "-- dialect: postgres\n-- Real PostgreSQL (compiled to WebAssembly) running in your browser. Nothing is stored anywhere.\nCREATE TEMP TABLE planets (\n  id          serial PRIMARY KEY,\n  name        text NOT NULL,\n  moons       int,\n  discovered  date\n);\n\nINSERT INTO planets (name, moons, discovered) VALUES\n  ('Mars',    2,  NULL),\n  ('Jupiter', 95, NULL),\n  ('Uranus',  28, '1781-03-13'),\n  ('Neptune', 16, '1846-09-23');\n\nSELECT * FROM planets ORDER BY id;\n\n-- Postgres-only goodies: RETURNING, FILTER, string_agg, generate_series\nUPDATE planets SET moons = moons + 1 WHERE name = 'Mars' RETURNING id, name, moons;\n\nSELECT count(*) FILTER (WHERE discovered IS NOT NULL) AS with_date,\n       string_agg(name, ', ' ORDER BY name)           AS names,\n       version()                                       AS server\nFROM planets;\n\nSELECT n, n * n AS square FROM generate_series(1, 5) AS n;\n"}, "groups": {"SQLite": ["SQLite: hello, temp table", "SQLite: joins with temp tables"], "PostgreSQL": ["PostgreSQL: hello, temp table"]}}, "shell": {"examples": {"Hello & navigation": "#!/bin/bash\n# Welcome to the shell playground — a SAFE, simulated Linux shell.\n# Nothing here touches your computer: the files live in a virtual filesystem.\necho \"Hello from $(whoami) on $(uname -s)!\"\necho \"I am in: $(pwd)\"\n\necho\necho \"--- what is in my home folder? ---\"\nls -la\n\necho\necho \"--- peek at a file ---\"\ncat notes.txt\n\necho\necho \"--- make a folder, step into it, create a file ---\"\nmkdir -p playground/deep/er\ncd playground\necho \"first line\" > hello.txt\necho \"second line\" >> hello.txt\ncat hello.txt\nwc -l hello.txt\n\necho\necho \"--- the whole tree ---\"\ncd ~\ntree\n", "Scripting basics": "#!/bin/bash\n# Variables, loops, functions, arrays and arithmetic.\nname=\"DevPortal\"\ncount=3\necho \"Welcome to $name — counting to $count:\"\nfor i in $(seq 1 $count); do\n  echo \"  step $i\"\ndone\n\n# a function with an argument and a return value via echo\nsquare() { echo $(( $1 * $1 )); }\necho \"7 squared = $(square 7)\"\n\n# an array\nfruits=(apple banana cherry)\necho \"I have ${#fruits[@]} fruits:\"\nfor f in \"${fruits[@]}\"; do\n  echo \" - $f (${#f} letters)\"\ndone\n\n# conditions\nn=17\nif [ $n -gt 10 ] && [ $((n % 2)) -eq 1 ]; then\n  echo \"$n is big and odd\"\nelse\n  echo \"$n is something else\"\nfi\n\n# case statement\nfor day in sat mon; do\n  case $day in\n    sat|sun) echo \"$day: weekend\" ;;\n    *)       echo \"$day: workday\" ;;\n  esac\ndone\n\n# while loop with arithmetic\ntotal=0; k=1\nwhile [ $k -le 5 ]; do total=$((total + k)); k=$((k + 1)); done\necho \"sum 1..5 = $total\"\n", "Pipes & text processing": "#!/bin/bash\n# The Unix superpower: small tools connected with pipes.\ncd ~/data\necho \"== people.csv ==\"\ncat people.csv\n\necho\necho \"== names only (cut) ==\"\ncut -d, -f1 people.csv | tail -n +2\n\necho\necho \"== sorted by age, oldest first (sort) ==\"\ntail -n +2 people.csv | sort -t, -k3 -nr | head -3\n\necho\necho \"== average age (awk) ==\"\ntail -n +2 people.csv | awk -F, '{ s += $3; n++ } END { printf \"%d people, average age %.1f\\n\", n, s/n }'\n\necho\necho \"== most common words (tr | sort | uniq -c) ==\"\ncat words.txt | tr 'A-Z' 'a-z' | tr -s ' ' '\\n' | sort | uniq -c | sort -nr | head -5\n\necho\necho \"== search + replace (grep, sed) ==\"\ngrep -E \" (404|500) \" access.log\necho \"hello world\" | sed 's/world/shell/'\n", "Log analysis": "#!/bin/bash\n# A tiny log-analysis pipeline over ~/data/access.log\nlog=~/data/access.log\necho \"total requests : $(wc -l < $log)\"\necho \"unique clients : $(awk '{print $1}' $log | sort -u | wc -l)\"\n\necho\necho \"--- requests per status code ---\"\nawk '{print $8}' $log | sort | uniq -c | sort -nr\n\necho\necho \"--- top 3 busiest clients ---\"\nawk '{print $1}' $log | sort | uniq -c | sort -nr | head -3\n\necho\necho \"--- every failing request (status >= 400) ---\"\nawk '$8 >= 400 { print $8, $6 }' $log\n\necho\necho \"--- write a report file ---\"\n{\n  echo \"REPORT\"\n  echo \"errors: $(awk '$8 >= 400' $log | wc -l)\"\n} > ~/report.txt\ncat ~/report.txt\n", "File management": "#!/bin/bash\n# Copy, move, rename and clean up files — in a sandbox where mistakes are free.\ncd ~\nmkdir -p backup/2024 work\nfor n in a b c; do echo \"file $n\" > work/$n.txt; done\nls work\n\ncp work/*.txt backup/2024/\nmv work/c.txt work/c-renamed.txt\necho \"--- after copy + move ---\"\nfind work backup -name \"*.txt\" | sort\n\necho\necho \"--- permissions ---\"\ntouch run-me.sh\nchmod +x run-me.sh\nls -l run-me.sh\n\necho\necho \"--- delete (nothing outside the sandbox can be harmed) ---\"\nrm -r backup\nls\n"}, "groups": {"Start here": ["Hello & navigation", "Scripting basics"], "Text tools": ["Pipes & text processing", "Log analysis"], "Files": ["File management"]}}};
